return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Arabic','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-10 13:26+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'ar','plural-forms'=>'nplurals=6; plural=n==0 ? 0 : n==1 ? 1 : n==2 ? 2 : n%100 >= 3 && n%100<=10 ? 3 : n%100 >= 11 && n%100<=99 ? 4 : 5;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'تم حفظ "%1$s %2$s".','"%1$s" created. %2$d template updated.'=>'تم إنشاء "%1$s". تم تحديث %2$d قالب.' . "\0" . 'تم إنشاء "%1$s". تم تحديث %2$d قوالب.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','"%s" created.'=>'تم إنشاء "%s".','"product" (replaces "article")'=>'"المنتج" (يحل محل "المقال")','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'"عامل H2 كمعادل H1" (الإعدادات → تحسين محركات البحث → التحليل): قم بتمكين هذا عندما يعرض السمة عنوان المنشور داخل H2 بدلاً من H1. يرفع المحلل H2 الأول إلى H1 حتى لا يتم خصم النقاط بشكل غير صحيح.','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d حرف — جيد، أعلى قليلاً من الحد الأقصى المثالي %2$d ولكن ضمن النطاق المقبول البالغ %3$d حرفًا. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d أحرف — الطول المثالي. %2$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d حرف — من المحتمل أن يتم اقتطاعه في نتائج البحث (ابقَ تحت %2$d). %3$s','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d أحرف — قصير جداً (استهدف %2$d–%3$d). %4$s','%1$d chars, %2$d words — good title.'=>'%1$d أحرف، %2$d كلمات — عنوان جيد.','%1$d internal, %2$d external.'=>'%1$d داخلي، %2$d خارجي.','%1$d of %2$d image(s) missing alt text.'=>'%1$d من %2$d صورة مفقودة النص البديل.','%1$d post tagged with _lf_lang = %2$s.'=>'تم وسم ٪1$d منشورًا بـ _lf_lang = ٪2$s.' . "\0" . 'تم وسم ٪1$d منشورات بـ _lf_lang = ٪2$s.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','%1$d words — below recommended minimum of %2$d.'=>'%1$d كلمة — أقل من الحد الأدنى الموصى به وهو %2$d.','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d كلمات — محتوى رقيق جداً. فكر في التوسع إلى %2$d كلمات على الأقل.','%d external link(s), no internal links.'=>'%d رابط خارجي، بدون روابط داخلية.','%d external link(s), no internal links. Add internal links to related content.'=>'%d رابط خارجي، بدون روابط داخلية. أضف روابط داخلية للمحتوى ذات الصلة.','%d H1 tags found — a page should have exactly one H1.'=>'تم العثور على %d علامة H1 — يجب أن تحتوي الصفحة على علامة H1 واحدة بالضبط.','%d image(s), all have alt text.'=>'%d صورة، جميعها تحتوي على نص بديل.','%d language not yet linked'=>'لم يتم ربط %d لغة بعد' . "\0" . 'لم يتم ربط %d لغات بعد' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','%d link updated.'=>'تم تحديث %d رابط.' . "\0" . 'تم تحديث %d روابط.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'لم يمكن حذف ملف اللغة تلقائيًا (%d ملفات اللغة). احذفه يدويًا عبر خادمك أو WP-CLI: wp language core uninstall <locale>.' . "\0" . 'لم يمكن حذف ملفات اللغة تلقائيًا (%d ملفات لغة). احذفها يدويًا عبر خادمك أو WP-CLI: wp language core uninstall <locale>.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','%d locale file removed.'=>'تم حذف ملف اللغة (%d ملف).' . "\0" . 'تم حذف ملفات اللغة (%d ملفات).' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','%d locale pack installed.'=>'تم تثبيت حزمة لغة واحدة (%d).' . "\0" . 'تم تثبيت حزم لغوية (%d).' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','%d navigation reference updated.'=>'تم تحديث مرجع تنقل %d.' . "\0" . 'تم تحديث مراجع التنقل %d.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','%d part reference updated.'=>'تم تحديث مرجع جزء %d.' . "\0" . 'تم تحديث مراجع الأجزاء %d.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','%d post'=>'منشور واحد' . "\0" . 'عدد المنشورات' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','%d rule registered'=>'تم تسجيل ٪d قاعدة' . "\0" . 'تم تسجيل ٪d قواعد' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','%d words.'=>'%d كلمات.','%s Archive'=>'%s الأرشيف','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s نشط ويخرج بالفعل JSON-LD الخاص بـ Schema.org. لقد عطل Lingua Forge إخراج المخطط الخاص به لمنع التداخل في الرسوم البيانية. على عكس Open Graph — حيث يضيف LF og:locale فوق مخرجات مكون إضافي آخر — لا يمكن إكمال المخطط بشكل نظيف: تكرار أو تداخل رسومات JSON-LD يؤدي إلى أخطاء في التحقق. عطل إخراج المخطط في المكون الإضافي المكتشف إذا كنت تريد أن يتولى LF التعامل مع البيانات المنظمة.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s نشط ويولد خريطة موقع خاصة به. تلك الخريطة منفصلة عن خريطة LF. يجب تقديم كلاهما إلى Google Search Console: خريطة الموقع الخاصة بمكون تحسين محركات البحث تعرض المحتوى الخاص بك؛ وخريطة LF تضيف روابط البديل متعددة اللغات. يتم الإعلان عن خريطة LF في robots.txt تلقائيًا.','(active)'=>'(نشط)','(avg %.1f hits/block)'=>'(متوسط %.1f نقرات/كتلة)','(avg %.1f hits/entry)'=>'(متوسط %.1f ضربات/مدخل)','(classic theme)'=>'(السمة الكلاسيكية)','(disabled)'=>'معطل','(FSE / block theme)'=>'(السمة FSE / الكتلة)','(no title) #%d'=>'(بدون عنوان) #%d','(partial)'=>'(جزئي)','(server/FPM timeout still applies)'=>'(لا تزال تنطبق مهلة الخادم / FPM)','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} لم يكن لديه روابط قابلة للاستبدال — أعد الفحص للتحقيق)','.txt file(s) in the directory'=>'.txt ملف(ات) في الدليل','/ 100'=>'/ 100','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — لم يتم العثور على عناوين H2 أو H3. إضافة H2s تحسن البنية.','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'H1 واحد ✓ — لا عناوين فرعية H2 (مقبول لنوع المحتوى هذا).','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'H1 واحد ✓ — لا يوجد H2، ولكن تم العثور على %d عنوان فرعي H3 (مثل رؤوس الأكورديون / التفاصيل). الهيكل مقبول.','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'H1 واحد ✓ — محتوى قصير (%d فقرة/فقرات)، العناوين الفرعية غير مطلوبة.','1 H1 ✓, %1$d H2, %2$d H3.'=>'H1 واحد ✓، %1$d H2، %2$d H3.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>لينغوا فورج:</strong> تم الاحتفاظ بـ %1$d قالبًا مترجمًا من سمة &#8220;%2$s&#8221; في قاعدة البيانات ولكنه غير نشط حاليًا. ستصبح نشطة مرة أخرى إذا قمت بإعادة تفعيل تلك السمة. لنقل ترجماتك إلى السمة الجديدة، أعد إنشائها عبر <strong>الإعدادات → لينغوا فورج → التوجيه → هيكل FSE</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> رابط قابل للإصلاح التلقائي','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> روابط بحاجة لمراجعة يدوية','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> مسار قديم','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> مشكلة في القالب','_lf_lang Coverage'=>'تغطية _lf_lang','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'يوجد ملف robots.txt مادي في جذر الموقع. يتم تجاوز robots.txt الافتراضي الخاص بـ WordPress — وفلتر Sitemap الخاص بـ LF —. خريطة LF غير معلنة لمحركات البحث.','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'يقبل فقط ملفات .mo المجمعة. يجب أن يتبع اسم الملف النمط {textdomain}-{locale}.mo. استبدال ملف بنفس الاسم سيقوم بالاستبدال.','Access forbidden — your account may be suspended or the key lacks the required permissions.'=>'تم حظر الوصول — قد يتم تعليق حسابك أو يفتقر المفتاح إلى الأذونات المطلوبة.','Action'=>'إجراء','active'=>'نشط','Active Languages'=>'اللغات النشطة','Active languages'=>'اللغات النشطة','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'اللغات النشطة: أضف كل لغة تريد دعمها. يحصل كل لغة على بادئة عنوان URL أو نطاق فرعي وعلامة hreflang في &lt;head&gt; الصفحة.','Active Plugins'=>'الإضافات النشطة','Active preset'=>'الإعدادات النشطة','Active Provider'=>'مزود نشط','Active theme'=>'السمة النشطة','Active: %s.'=>'نشط: %s.','Add entry'=>'إضافة إدخال','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'أضف تعليمات لتحسين المسودة — مثلاً اجعله أقصر، أضف قسم خاتمة، استخدم سجل أكثر رسمية، أدرج قسم الأسئلة الشائعة…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'أضف تعليمات لتحسين المسودة — مثلاً اجعلها أقصر، أضف قسم الخاتمة، استخدم سجلًا أكثر رسمية…','Add key →'=>'إضافة مفتاح →','Add new entry'=>'إضافة إدخال جديد','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'أضف مصطلحًا واحدًا في كل سطر. كل من المصطلح المصدر والعرض المستهدف مطلوبان. يحدد زوج اللغة الوظائف التي ينطبق عليها القيد.','Add Sitemap directive to robots.txt'=>'أضف توجيه Sitemap إلى robots.txt','Add the following line to your robots.txt manually:'=>'أضف السطر التالي إلى robots.txt يدويًا:','Add WooCommerce product tags to Open Graph output'=>'أضف علامات منتجات WooCommerce إلى إخراج Open Graph','Adds a link to the home page so visitors can browse in their language.'=>'يضيف رابطًا إلى الصفحة الرئيسية حتى يتمكن الزوار من التصفح بلغتهم.','Administrators only (manage_options)'=>'المسؤولون فقط (إدارة_الخيارات)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'بعد تغيير اللغة الأساسية، قم بتفريغ الروابط الدائمة (القسم أدناه) لتحديث توجيه URL.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'بعد تغيير إعدادات هيكل URL (بادئة المسار ↔ النطاق الفرعي)، قم دائمًا بزيارة الإعدادات → روابط دائمة وانقر على حفظ التغييرات لتفريغ قواعد إعادة الكتابة.','AI analysis failed. Please try again.'=>'فشل تحليل الذكاء الاصطناعي. يرجى المحاولة مرة أخرى.','AI Behaviour Preset'=>'إعداد سلوك الذكاء الاصطناعي','AI cache cleared. %d entry was removed.'=>'تم مسح ذاكرة التخزين المؤقت للذكاء الاصطناعي. تم إزالة %d إدخال.' . "\0" . 'تم مسح ذاكرة التخزين المؤقت للذكاء الاصطناعي. تم إزالة %d إدخالات.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'ذاكرة التخزين المؤقت للذكاء الاصطناعي: قائمة الاستجابات المخزنة مؤقتًا مع عدد الضربات. امسح الذاكرة المؤقتة بأكملها أو إدخالات منشور واحد. استخدم "مسح" قبل اختبار تغيير الترجمة — يتم إرجاع النتائج المخزنة مؤقتًا حتى يتم إخلاء إدخال الذاكرة المؤقتة عند تغيير إعدادات الذكاء الاصطناعي أو النموذج.','AI Configuration'=>'إعدادات الذكاء الاصطناعي','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'ميزات الذكاء الاصطناعي اختيارية. التوجيه اللغوي، hreflang، مفتاح التبديل اللغوي، ونظام مجموعة الترجمة كلها تعمل بدون مزود مكون.','AI Limits & Security'=>'حدود و أمان الذكاء الاصطناعي','AI Provider'=>'مزود الذكاء الاصطناعي','AI provider returned an empty response.'=>'استجابة فارغة من مزود الذكاء الاصطناعي.','AI Recommendations'=>'توصيات الذكاء الاصطناعي','AI returned an unexpected response format. Please try again.'=>'عاد الذكاء الاصطناعي بتنسيق استجابة غير متوقع. يرجى المحاولة مرة أخرى.','AI translation and batch analysis may time out. Recommend 120s or more.'=>'قد تتوقف الترجمة التلقائية وتحليل الدُفعات. يُنصَح بـ 120 ثانية أو أكثر.','AI Usage'=>'استخدام الذكاء الاصطناعي','AI Usage & Cache'=>'استخدام الذكاء الاصطناعي والذاكرة المؤقتة','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'استهدف 120–160 حرفًا. اتركه فارغًا لاستخدام بديل المقتطف.','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'تكتشف جميع محركات البحث الكبرى — Google وBing وYandex — خريطة الموقع تلقائيًا عبر توجيه Sitemap: في robots.txt. لا حاجة لاتخاذ إجراء يدوي. ترسل الأزرار أدناه تنبيهًا فوريًا بحيث يعيد المحرك الزحف على خريطة الموقع الآن بدلاً من الانتظار لفحص robots.txt المجدول التالي.','All published posts have a _lf_lang value. No gaps detected.'=>'جميع المنشورات المنشورة لها قيمة _lf_lang. لم يتم الكشف عن فجوات.','All time'=>'جميع الأوقات','All types'=>'جميع الأنواع','Allow editors to lock individual blocks'=>'السماح للمحررين بقفل الكتل الفردية','Allow Gutenberg template-editing mode on post screens'=>'السماح بوضع تحرير النموذج في صفحات المنشور','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'احذف أيضًا تعيينات اللغة، علاقات الترجمة، الأوصاف التعريفية، القاموس، وذاكرة الترجمة عند إلغاء تثبيت الإضافة.','Also generate meta description'=>'أيضًا إنشاء وصف ميتا','Alternative (server-side):'=>'بديل (جانب الخادم):','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'دائمًا إصدار og:locale و og:locale:alternate فقط. يُستخدم عندما يتولى مكون إضافي أو سمة التعامل مع مجموعة OG الكاملة.','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'دائمًا إصدار مجموعة OG + Twitter Card الكاملة بغض النظر عن المكونات الإضافية الأخرى. يُستخدم فقط إذا لم يُصدر مكون إضافي آخر علامات OG.','An unknown error occurred.'=>'حدث خطأ غير معروف.','Analyse'=>'تحليل','Analyse all languages'=>'تحليل جميع اللغات','Analyse…'=>'تحليل…','Analysis'=>'التحليل','Analysis request failed. Please try again.'=>'فشل طلب التحليل. يرجى المحاولة مرة أخرى.','Analyzing…'=>'جارٍ التحليل…','and'=>'و','Anthropic (Claude)'=>'أنثروبيك (كلود)','Anthropic Console'=>'وحدة تحكم أنتروبيا','any'=>'أي','API calls saved by cache'=>'نداءات API محفوظة بواسطة الذاكرة المؤقتة','API Key'=>'مفتاح API','API Keys'=>'مفاتيح API','API Keys Tab'=>'علامة تبويب مفاتيح API','API Response Cache'=>'ذاكرة التخزين المؤقت لاستجابة API','API Response Cache setting saved.'=>'تم حفظ إعدادات ذاكرة التخزين المؤقت لاستجابة API.','Appends the following line to your existing robots.txt: %s'=>'يضيف السطر التالي إلى ملف robots.txt الخاص بك: %s','Applied ✓'=>'مُطبَّق ✓','Apply failed — please try again.'=>'فشل التطبيق — يرجى المحاولة مرة أخرى.','Apply to all language versions'=>'تطبيق على جميع إصدارات اللغة','Apply to Block'=>'تطبيق على الحاشية','Apply to Editor'=>'تطبيق على المحرر','Apply to Footnote'=>'تطبيق على الحاشية','Apply to Meta Description'=>'تطبيق على الوصف التعريفي','Apply translation'=>'تطبيق الترجمة','Applying…'=>'جارٍ التطبيق…','Approximate size'=>'الحجم التقريبي','Archive'=>'أرشيف','Archive: %s'=>'الأرشيف: %s','Article / WebPage'=>'مقال / صفحة ويب','Article / WebPage — all singular posts and pages'=>'مقال / صفحة ويب — جميع المنشورات والصفحات المفردة','Authors and above (edit_published_posts)'=>'المؤلفون وما فوق (تحرير_نشر_المشاركات)','Auto (recommended)'=>'تلقائي (موصى به)','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'تقوم التعيينات التلقائية: منتجات WooCommerce → ملف المنتج؛ الصفحة الرئيسية الثابتة → ملف الصفحة المقصودة؛ وكل شيء آخر → ملف المدونة. اختر ملفًا معينًا لتجاوز هذا لجميع المنشورات.','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'تم اكتشافه تلقائيًا للصفحة الثابتة؛ يمكن تحديده يدويًا. العنوان 20 نقطة · الوصف التعريفي 30 نقطة · عدد الكلمات 15 نقطة · العناوين 10 نقاط · الصور 15 نقطة · الروابط 0 نقطة. حد عنوان SERP 70 حرفًا؛ التحذير عند أقل من 150 كلمة، الفشل عند أقل من 60؛ H2 والروابط الداخلية اختيارية.','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'تم اكتشافه تلقائيًا لمنتجات WooCommerce. العنوان 20 نقطة · الوصف التعريفي 30 نقطة · عدد الكلمات 15 نقطة · العناوين 5 نقاط · الصور 20 نقطة · الروابط 0 نقطة. حد عنوان SERP 70 حرفًا؛ التحذير عند أقل من 80 كلمة، الفشل عند أقل من 40؛ H2 والروابط الداخلية اختيارية.','Available models reference'=>'مرجع النماذج المتاحة','avg'=>'متوسط','Batch Analysis'=>'تحليل الدُفعة','Behavior'=>'السلوك','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'السلوك: اختر إعداد الذكاء الاصطناعي (حرفي، متوازن، إبداعي)، أضف تعليمات مخصصة للموقع بأكمله، قم بتمكين أو تعطيل الترجمة التلقائية بعد الحفظ، وتهيئة ذاكرة الترجمة.','Block Content'=>'محتوى الكتلة','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'يعرض إشعارًا مؤدبًا عندما يتم عرض الصفحة الحالية بلغتها الأصلية لأنه لا توجد ترجمة للغة الزائر. يقوده إشارة LINGUAFORGE_LANG_FALLBACK_ACTIVE لموجه لينجوا فورج — لا يصدر شيئًا عندما توجد ترجمة للغة الطلب.','Block Editor'=>'محرر الكتلة','block keywordfallback'=>'البديل','block keywordi18n'=>'i18n','block keywordlanguage'=>'اللغة','block keywordlinguaforge'=>'لينجوا فورج','block keywordtranslation'=>'الترجمة','Block locking'=>'قفل الكتلة','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'أنماط الكتل المسجلة لأنواع المنشورات المخصصة. استخدم زر الترجمة لإنتاج نسخة بلغة أخرى. يتم حفظ المحتوى المترجم هنا ويمكن نسخه إلى أي منشور CPT من أداة إدراج الأنماط في محرر الكتل أو استخدامه كنقطة انطلاق لنمط متزامن (كتلة قابلة لإعادة الاستخدام).','block titleMissing Translation Notice'=>'إشعار الترجمة المفقودة','Block translation reuses'=>'إعادة استخدام ترجمات الكتل','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'ذاكرة التخزين المؤقت للترجمة على مستوى الكتلة مشتركة عبر المنشورات. عند التمكين، يتم تقديم الكتل المتطابقة (نفس العلامة، زوج اللغة، والقاموس) من الذاكرة بدلاً من استدعاء الذكاء الاصطناعي مرة أخرى. تعديلات القاموس وتغييرات الإعداد المسبق للامتثال تلغي تلقائيًا الترجمات المخزنة المؤقتة المتأثرة.','Blog / Editorial'=>'مدونة / تحرير','Blog / Editorial (default)'=>'مدونة / تحرير (افتراضي)','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'تستخدم منشورات المدونة المقال؛ جميع أنواع المنشورات والصفحات الأخرى تستخدم صفحة ويب. يتضمن العنوان، الوصف، inLanguage، الرابط، تاريخ النشر، تاريخ التعديل، الصورة، والناشر.','Browser language redirect'=>'إعادة توجيه لغة المتصفح','Built-in preset instructions:'=>'تعليمات الإعداد المسبق المدمجة:','Bulletize (•-prefixed)'=>'قائمة نقطية (مُعلمة بـ •)','cached'=>'مخبأ','Cached API responses'=>'استجابات API المخزنة مؤقتًا','Cached block translations'=>'ترجمات الكتل المخزنة مؤقتًا','Cancel'=>'إلغاء','Cannot determine target language from slug.'=>'لا يمكن تحديد اللغة الهدف من الرابط المختصر.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'لا يمكن الكتابة إلى المنتج %1$d: هو نسخة مترجمة (اللغة: %2$s)%3$s. يجب تحديث البيانات التشغيلية (السعر، المخزون، SKU، الأبعاد) على المنتج المصدر. حل معرف المنتج المصدر عبر: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>'علامة canonical','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'تحديد مقدار استخدام الذكاء الاصطناعي الذي يمكن للموقع توليده وتقييد الأدوار التي يمكنها تشغيل مكالمات الذكاء الاصطناعي المدفوعة. يتوضع فوق حد المعدل لكل مستخدم (30 طلبًا / دقيقة، مبرمج بشكل ثابت) الذي يحمي بالفعل من حلقات الجري غير المحدودة لمستخدم واحد.','Cart'=>'عربة التسوق','chars'=>'حروف','Check your account, billing, or remaining credits directly on the provider console:'=>'تحقق من حسابك، الفوترة، أو الرصيد المتبقي مباشرة على وحدة تحكم المزود:','Checkout'=>'الدفع','Chunk translated'=>'تمت ترجمة الجزء','Chunk translated to:'=>'تمت ترجمة الجزء:','Clear'=>'مسح','Clear All'=>'مسح الكل','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'هل تريد مسح جميع نتائج الذكاء الاصطناعي المخزنة مؤقتًا؟ ستؤدي الطلبات المستقبلية إلى استدعاءات API جديدة حتى يتم إعادة بناء الذاكرة المؤقتة.','Clear API Response Cache'=>'مسح ذاكرة التخزين المؤقت لاستجابة API','Clear Debug Files'=>'مسح ملفات التصحيح','Clear hints'=>'مسح التلميحات','Clear input'=>'مسح الإدخال','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'هل تريد مسح ذاكرة الترجمة بالكامل؟ ستقوم الترجمات المستقبلية بإعادة بناء الكاش أثناء تشغيلها.','Clear Translation Memory'=>'مسح ذاكرة الترجمة','Close'=>'إغلاق','Close language panel'=>'إغلاق لوحة اللغة','Close popover'=>'إغلاق النافذة المنبثقة','Compatibility'=>'التوافق','Compliance Preset'=>'إعدادات الامتثال','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'قم بتكوين مزود AI في الإعدادات → مفاتيح API لتمكين التوصيات المدعومة بالذكاء الاصطناعي.','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'إعداد hreflang، Open Graph، Schema.org، خرائط الموقع، والمشاركة الاجتماعية لكل لغة على موقعك. يتعامل كل قسم أدناه مع جانب واحد من تحسين محركات البحث متعدد اللغات.','Configured'=>'تم التكوين','Contact Form 7 (wpcf7_contact_form) is excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'يتم استبعاد نموذج الاتصال 7 (wpcf7_contact_form) تلقائيًا. أضف أي أنواع منشورات طرف ثالث أخرى يجب عدم تصفية محتواها حسب اللغة، سطر واحد لكل منها أو مفصولة بفواصل.','Content generated'=>'تم إنشاء المحتوى','Content Generator'=>'مولد المحتوى','Content profiles and weights'=>'ملفات التعريف بالمحتوى والأوزان','Content ready'=>'المحتوى جاهز','Contributors and above — default (edit_posts)'=>'المساهمون وما فوق — الافتراضي (تحرير_المشاركات)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'تحكم في مقدار المحتوى المرسل إلى الذكاء الاصطناعي ومدى حجم الاستجابة الممكن. اترك حقلًا فارغًا لاستخدام الافتراضي المدمج (المعروض كمحدد موضع). قم برفع هذه القيم إذا كانت الصفحات الكبيرة تُقطع؛ وخفضها لتقليل تكاليف API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'يتحكم في ميزانية الرموز وحدود الإدخال لميزة مولد محتوى الذكاء الاصطناعي. اترك الحقول فارغة لاستخدام الإعدادات الافتراضية المدمجة.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'يحدد ما يحدث عندما يقوم مسؤول بحذف الإضافة من الإضافات → الإضافات المثبتة → حذف. يتم دائمًا حذف إعدادات الإضافة وذاكرة التخزين المؤقت للذكاء الاصطناعي. يتم الاحتفاظ بتعيينات اللغة والعلاقات الترجمة بشكل افتراضي بحيث يمكن لمسح غير مقصود أو إعادة تثبيت أن يستأنف من حيث توقف.','Conversational'=>'محادثة','Copied ✓'=>'تم النسخ ✓','Copied!'=>'تم النسخ!','Copy'=>'نسخ','Copy and paste into a GitHub issue or support request.'=>'نسخ ولصق في مشكلة GitHub أو طلب دعم.','Copy failed — please copy the URL manually.'=>'فشل النسخ — يرجى نسخ الرابط يدويًا.','Copy markup'=>'نسخ التعليمات البرمجية','Copy system info'=>'نسخ معلومات النظام','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'انسخ الرابط الحالي إلى الحافظة. يعرض رسالة "تم نسخ الرابط" عند النجاح.','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'انسخ النتيجة والصقها حيثما دعت الحاجة (مثلاً مباشرة في حقل الحاشية السفلية).','Copy to safe storage'=>'نسخ إلى التخزين الآمن','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'إجراءات JS النسخ/الاصلي/التلقائي: تتم معالجتها بواسطة social-share.js الخاص بـ LF','Could not add entry: source term and target term are required.'=>'تعذر إضافة الإدخال: يتطلب الأمر المصطلح المصدر والمصطلح الهدف.','Could not copy the file. Check that the uploads folder is writable.'=>'تعذر نسخ الملف. تحقق من أن مجلد التحميلات قابل للكتابة.','Could not instantiate the provider.'=>'تعذر إنشاء المزود.','Could not save the file. Check that the uploads folder is writable.'=>'تعذر حفظ الملف. تحقق من أن مجلد التحميلات قابل للكتابة.','Could not save the glossary entry.'=>'تعذر حفظ إدخال المصطلح.','Could not write to robots.txt. Check file permissions.'=>'تعذر الكتابة إلى robots.txt. تحقق من أذونات الملف.','CPT Block Patterns'=>'أنماط كتل CPT','Create'=>'إنشاء','Create missing'=>'إنشاء مفقود','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'إنشاء ترجمات لنوع المنشور "%s" يتطلب تكامل نشط. يرجى التأكد من تثبيت وتفعيل التكامل المطلوب.','Creating…'=>'جارٍ الإنشاء…','Creative / Marketing'=>'إبداعي / تسويقي','Creative / Marketing instructions'=>'تعليمات إبداعية / تسويقية','Current content (will be overwritten)'=>'المحتوى الحالي (سيتم استبداله)','Current status'=>'الحالة الحالية','Current title'=>'العنوان الحالي','Current: {current}'=>'الحالي: {current}','Currently emitting'=>'يصدر حالياً','Currently inherited from the %s constant. Selecting a value here will override it.'=>'موروث حاليًا من الثابت %s. اختيار قيمة هنا سيقوم بتجاوزها.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'حاليًا يتم تخطيها للمنشورات التي تستخدم عناصر نائب عن طريق تعليق الكتلة (حقول wp:details الملخص، إلخ) — فهي تمر إلى مسار الترجمة ذو الطلب الواحد الموجود.','Currently:'=>'حاليًا:','Custom'=>'مخصص','Custom tables — LF post-meta filters do not affect orders.'=>'الجداول المخصصة — مرشحات ميتا المنشور LF لا تؤثر على الطلبات.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'تم الوصول إلى الحصة اليومية للذكاء الاصطناعي (%1$d طلبات). تتجدد في %2$s بالتوقيت العالمي المنسق.','Daily quota'=>'الحصة اليومية','Daily request limit'=>'حد الطلب اليومي','Danger Zone'=>'منطقة الخطر','Debug Files'=>'ملفات التصحيح','Debug files cleared. %d file was removed.'=>'تم مسح ملفات التصحيح. تم حذف ملف واحد.' . "\0" . 'تم مسح ملفات التصحيح. تم حذف %d ملفات.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','Debug Info'=>'معلومات التصحيح','Debug logging'=>'تسجيل التصحيح','Debug logging disabled.'=>'تم تعطيل تسجيل التصحيح.','Debug logging enabled.'=>'تم تفعيل تسجيل التصحيح.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'تصحيح: تمكين سجل التصحيح لالتقاط مطالبات الذكاء الاصطناعي واستجابات API في ملف محلي. تعطيل بعد استكشاف الأخطاء وإصلاحها — يكتب وضع التصحيح ملفًا في كل طلب للذكاء الاصطناعي.','Default OG image'=>'صورة OG الافتراضية','Default profile'=>'الملف الشخصي الافتراضي','Delete'=>'حذف','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'هل تريد حذف جميع ملفات .txt في دليل التصحيح؟ سيظل الدليل نفسه موجودًا حتى تستمر عمليات التصحيح المستقبلية في الوصول إليه بشكل نظيف.','Delete all files for this override (both .mo and .po)?'=>'هل تريد حذف جميع الملفات لهذا التجاوز (ملفات .mo و .po)؟','Delete content data on uninstall'=>'حذف بيانات المحتوى عند إلغاء التثبيت','Delete this glossary entry?'=>'هل تريد حذف إدخال المصطلح هذا؟','Describe what to write — topic, key points, structure…'=>'صف ما تريد كتابته — الموضوع، النقاط الرئيسية، الهيكل…','Destructive action — read before proceeding'=>'إجراء تدميري — اقرأ قبل المتابعة','Details ↗'=>'التفاصيل ↗','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'اكتشاف إضافات SEO النشطة (Yoast، Rank Math، وغيرها) أثناء التشغيل. إصدار فقط og:locale + og:locale:alternate عندما يكون هناك إضافة أخرى تنتج بالفعل مجموعة OG الكاملة؛ إصدار المجموعة الكاملة عندما لا يتم اكتشاف أي منها.','Directory'=>'الدليل','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'تعطيل فقط للمواقع بدون رأس أو لتنفيذ hreflang مخصص بالكامل. عند التعطيل، لا تزال LF تزيل الوسم canonical الخاص بـ WordPress ولا تمنع إخراج hreflang الخاص بإضافة SEO.','Disabled'=>'معطل','Disabled (by setting)'=>'معطل (عن طريق الإعداد)','Disabled (mode setting)'=>'معطل (إعداد الوضع)','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'معطل لأن إضافة lf-social-share mu-plugin تقدم هذه الميزة بالفعل.','DISALLOW_FILE_MODS is set.'=>'تم تعيين DISALLOW_FILE_MODS.','Display'=>'عرض','Displays the Lingua Forge language switcher.'=>'يعرض مبدل لغة لينغوا فورج.','Do not output any OG tags.'=>'لا تصدر أي علامات OG.','Documentation'=>'توثيق','Done'=>'تم','Done — {done} of {total} post(s) fixed.'=>'تم — تم إصلاح {done} من {total} منشور.','Down'=>'أسفل','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'قم بتنزيل وتثبيت حزمة لغة ووردبريس الأساسية مباشرة من WordPress.org. بمجرد التثبيت، تصبح اللغة متاحة لتوجيه URL وسير عمل الترجمة بالذكاء الاصطناعي. يتم جلب قائمة اللغات المتاحة عند الطلب — انقر على الزر أدناه لتحميلها.','Dropdown direction'=>'اتجاه القائمة المنسدلة','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'كل مقياس يعطي واحدًا من أربعة حالات: حسن (الوزن الكامل)، تحذير (50% من الوزن)، فشل (0)، أو معلومات (0، بدون خصم). درجة ≥ 80 خضراء، 50–79 كهرماني، أقل من 50 حمراء.','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'يتم تقييم كل منشور من 0 إلى 100 بناءً على ستة مقاييس قائمة على القواعد: العنوان، الوصف التعريفي، عدد الكلمات، هيكل العناوين، تغطية النص البديل للصور، والروابط الداخلية. يتم دائمًا منح عشر نقاط لوقت القراءة (معلوماتي فقط). يتم توزيع الـ 90 نقطة المتبقية عبر المقاييس الأخرى بأوزان تختلف حسب ملف المحتوى (انظر أدناه).','edit'=>'تحرير','Editors and above (edit_others_posts)'=>'المحررون وما فوق (تحرير_مشاركات_الآخرين)','Enable API response caching'=>'تمكين التخزين المؤقت لاستجابة API','Enable block-level translation cache reuse across posts'=>'تمكين إعادة استخدام ذاكرة التخزين المؤقت للترجمة على مستوى الكتلة عبر المنشورات','Enable Social Share URL rewriting for Social Icons blocks'=>'تمكين إعادة كتابة عنوان URL لمشاركة وسائل التواصل الاجتماعي لكتل أيقونات التواصل الاجتماعي','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'قم بتمكينه عندما يعرض قالبك عنوان المنشور كـ H2 بدلاً من H1 (شائع في بعض قوالب الكتل). يقوم المحلل بجلب الصفحة المعروضة، وإذا لم يجد H1 ولكنه وجد H2، فإنه يرفع أول H2 إلى H1 لأغراض التقييم.','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'أدخل مفتاح API الخاص بك لواحد على الأقل من مزودي الذكاء الاصطناعي. يتم تشفير المفاتيح عند الراحة باستخدام AES-256-GCM مع سر خاص بالموقع (LINGUAFORGE_SECRET). لا تشارك تصديرات قاعدة البيانات بدون تدوير السر أولاً.','Environment'=>'البيئة','environment variable'=>'متغير البيئة','Error'=>'خطأ','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'في كل مرة يتم فيها تحليل منشور، يتم تخزين الدرجة في ميتا المنشور. يظهر عمود اللغة في قائمة المنشورات شارة "SEO N" ملونة لأي منشور تم تحليله مرة واحدة على الأقل. عندما يتم تخزين درجتين، يظهر مؤشر التغير (↑N / ↓N) الذي يُظهر التغيير منذ التشغيل السابق.','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'مطلوب H1 واحد بالضبط. عادةً يكون H1 هو عنوان المنشور الذي يعرضه السمة — يُقرأ من الصفحة المعروضة مباشرة عند الإمكان، ومن محتوى المنشور كبديل.','Exclude from navigation menus'=>'استبعاد من قوائم التنقل','Exclude from routing'=>'استبعاد من التوجيه','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'استبعاد نوع المنشور هذا من التوجيه اللغوي — لن تظهر منشوراته بعد الآن هنا أو تتلقى _lf_lang. لا يمكن التراجع عن ذلك تلقائيًا.','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'هل تريد استبعاد نوع المنشور هذا من التوجيه اللغوي؟ لن تظهر منشوراته بعد الآن في هذه القائمة أو تتلقى _lf_lang. يمكنك عكس ذلك في الإعدادات → الموجه → استثناءات مرشح الاستعلام.','excluded from routing'=>'تم استبعاده من التوجيه','Excluded post types'=>'أنواع المنشورات المستبعدة','Excluding…'=>'جارٍ الاستبعاد…','Expand'=>'وسّع','Expected: {expected}'=>'متوقع: {expected}','External share services'=>'خدمات المشاركة الخارجية','Extra guidance — tone, style, constraints, target audience…'=>'إرشادات إضافية — النغمة، الأسلوب، القيود، الجمهور المستهدف…','Extra guidance — tone, style, constraints…'=>'إرشادات إضافية — النغمة، الأسلوب، القيود…','Failed to save exclusion.'=>'فشل في حفظ الاستبعاد.','Failed. Please try again.'=>'فشل. يرجى المحاولة مرة أخرى.','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'عنوان URL للصورة الاحتياطية المستخدمة عندما لا تحتوي الصفحة على صورة مميزة أو شعار الموقع أو أيقونة الموقع. تظهر في معاينات وسائل التواصل الاجتماعي للأرشيفات، وفهرس المدونة، وأي صفحة فردية بدون صورة مصغرة.','Feature'=>'الميزة','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'يتم تصنيف الميزات إلى مستويين. أدخل معرف النموذج الدقيق لكل مستوى ومزود. اترك حقلًا فارغًا لاستخدام الإعداد الافتراضي المدمج (المعروض كعنصر نائب). يتم استدعاء نماذج المزود النشط فقط عند التشغيل — قم بتكوين الآخرين مسبقًا إذا كنت تخطط للتبديل.','File copied to safe storage successfully.'=>'تم نسخ الملف إلى التخزين الآمن بنجاح.','File modifications are disabled (DISALLOW_FILE_MODS).'=>'تم تعطيل تعديلات الملفات (DISALLOW_FILE_MODS).','Files'=>'الملفات','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'تصل الملفات إلى الدليل أدناه. مفيد لتشخيص مشكلات الترجمة — قم بإيقاف التشغيل بمجرد أن تحصل على ما تحتاجه حتى لا تتراكم الملفات. يمكنك أيضًا فرض ذلك من wp-config.php باستخدام `define( \'LINGUAFORGE_AI_DEBUG\', true );` الذي يتجاوز التبديل.','Filter'=>'تصفية','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'تصفية حسب اللغة ونوع المنشور، تصفح المحتوى الخاص بك، وانقر على تحليل لتشغيل تدقيق SEO قائم على القواعد — طول العنوان، الوصف التعريفي، عدد الكلمات، هيكل العناوين، تغطية نص بديل الصورة، والروابط الداخلية.','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'مرر مع linguaforge_debug_dir لإعادة توجيه مخرجات التصحيح إلى موقع غير عام.','Finding'=>'جارٍ البحث','Fix'=>'إصلاح','Fix All'=>'إصلاح الكل','Fix all links'=>'تصحيح جميع الروابط','Fix all parts'=>'تصحيح جميع الأجزاء','Fix Links'=>'تصحيح الروابط','Fix Nav'=>'تصحيح التنقل','Fix Parts'=>'تصحيح الأجزاء','Fix Template'=>'إصلاح القالب','Fixing {n} / {total}…'=>'جارٍ إصلاح {n} / {total}…','Fixing…'=>'جارٍ الإصلاح…','Flush Permalink Rules'=>'مسح قواعد الرابط الثابت','Flush Permalinks'=>'مسح الروابط الثابتة','Flush Sitemap Cache'=>'تحديث ذاكرة التخزين المؤقت لخريطة الموقع','Footnote Content'=>'محتوى الحاشية','footnote(s) translated — applied together with content.'=>'تمت ترجمة الحاشية السفلية — تم تطبيقها مع المحتوى.','Footnotes'=>'الحواشي السفلية','Footnotes payload (advanced)'=>'حمولة الحواشي السفلية (متقدم)','Forbidden'=>'ممنوع','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'مُجبر على الإيقاف من قبل الثابت LINGUAFORGE_AI_DEBUG في wp-config.php. احذف تلك السطر للتحكم في هذا التبديل من هنا.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'مُجبر على التشغيل من قبل الثابت LINGUAFORGE_AI_DEBUG في wp-config.php. احذف تلك السطر للتحكم في هذا التبديل من هنا.','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'يجبر إعادة إنشاء خريطة الموقع في الطلب التالي. يستخدم بعد استيراد جماعي أو تحرير يدوي لعلاقات الترجمة.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'تم العثور على {parts} عبر <strong>{total}</strong> من منشورات و صفحات <strong>{scanned}</strong> التي تم فحصها للغة <strong>{lang}</strong>.','From'=>'من','Front Page'=>'الصفحة الرئيسية','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'توطين FSE: إنشاء، ترجمة، وإصلاح الروابط في قوالب وتجزئة قوالب التعديل الكامل للموقع مباشرة من علامة التبويب هذه.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'تم زرع قوالب FSE من السمة النشطة. أنشئها ثم قم بتخصيصها في محرر الموقع.','Full'=>'كامل','Full Article'=>'المقال الكامل','Full post'=>'المقال كامل','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'ترجمة الصفحة الكاملة، منشئ المحتوى (نماذج الطبقة المتوسطة كافية تمامًا)','General'=>'عام','Generate'=>'إنشاء','Generate Content'=>'إنشاء المحتوى','Generate content…'=>'إنشاء المحتوى…','Generate Excerpt'=>'إنشاء مقتطف','Generate Meta Description'=>'إنشاء وصف ميتا','Generate the multilingual sitemap at /lf-sitemap.xml'=>'إنشاء خريطة الموقع متعددة اللغات في /lf-sitemap.xml','Generated Content'=>'المحتوى المولد','Generated meta description'=>'وصف ميتا مولد','Generating…'=>'جارٍ التوليد…','Generation failed.'=>'فشل التوليد.','Getting started'=>'البدء','Global AI preset'=>'إعدادات الذكاء الاصطناعي العالمية','Global default (%s)'=>'الإعداد الافتراضي العالمي (%s)','Glossary'=>'القاموس','Glossary entry added.'=>'تمت إضافة إدخال المصطلح.','Glossary entry removed.'=>'تمت إزالة إدخال المصطلح.','Glossary Tab'=>'علامة تبويب القاموس','Google (Gemini)'=>'جوجل (جميني)','Google AI Studio'=>'استوديو جوجل للذكاء الاصطناعي','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'تم تفعيل وضع H2 كـ H1 — يُحتسب العنوان كمعادل لـ H1. (لم يتم الكشف عن علامات العنوان من الصفحة المعروضة؛ تحقق من أن قالبك يعرض العنوان بشكل صحيح.)','Heading structure rules'=>'قواعد هيكل العناوين','Headings'=>'عناوين','Hide'=>'إخفاء','High-Performance Order Storage (HPOS)'=>'تخزين الطلبات عالي الأداء (HPOS)','Hints'=>'تلميحات','Home link text'=>'نص رابط الصفحة الرئيسية','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'كيف يجب أن تظهر في الترجمة. اكتب نفس قيمة المصطلح المصدر لتوجيه الذكاء الاصطناعي للحفاظ عليه حرفيًا.','How to use'=>'كيفية الاستخدام','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + مزامنة CPT — انتقالية؛ مرشحات ميتا المنشور LF تنطبق على نسخة CPT.','Hreflang'=>'Hreflang','Hreflang output'=>'إخراج hreflang','Hreflang settings saved.'=>'تم حفظ إعدادات hreflang.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'رمز + تسمية','Icon only'=>'رمز فقط','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'إذا تم تحديده، فإن إلغاء تثبيت الإضافة سيحذف بشكل دائم جميع تعيينات اللغة، علاقات الترجمة، الأوصاف التعريفية، الإعدادات المسبقة للصفحات، قاموس الذكاء الاصطناعي، وذاكرة الترجمة لكل منشور على هذا الموقع. لا يمكن التراجع عن ذلك. اتركه غير محدد إلا إذا كنت تزيل دعم التعددية اللغوية من الموقع بالكامل.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'إذا كان لديك إضافة SEO عامة مثبتة، يُظهر هذا اللوح كيف يتكيف LF لتجنب الإخراج المكرر. الهدف هو تجنب التصادم — وليس التعاون. دائمًا ما يوفر LF طبقة SEO متعددة اللغات (hreflang، og:locale، inLanguage schema) التي تتطلب معرفة تكوين توجيه اللغة الخاص بـ LF لإنتاجها بشكل صحيح.','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'إذا كانت لديك Yoast SEO، Rank Math، All in One SEO، أو SEOPress مثبتة، يكتشفها Lingua Forge ويتكيف لتجنب الإخراج المكرر. بالنسبة لـ hreflang، يتولى LF الأمر بالكامل ويمنع إخراج الإضافة لأنها لا يمكنها إنتاج hreflang صحيح لتكوين توجيه متعدد اللغات. بالنسبة لـ Open Graph، يضيف LF فقط og:locale و og:locale:alternate — الإشارات متعددة اللغات التي لا يمكن للإضافة توفيرها — ويترك مجموعة OG الأساسية للإضافة. بالنسبة لـ Schema.org، يعطل LF إخراجه الخاص تمامًا لتجنب تضارب مخططات JSON-LD.','Images'=>'صور','Improve writing'=>'تحسين الكتابة','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'في محرر الكتل، أضف كتلة أيقونات التواصل الاجتماعي. لكل أيقونة، افتح إعدادات الرابط وأدخل أحد القيم "share:" أدناه كعنوان URL. على الواجهة الأمامية، يستبدله LF بعنوان URL للمشاركة الصحيح للصفحة الحالية.','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'يشمل الاسم، الوصف، inLanguage، عنوان URL، الصورة، وعرض مع السعر، عملة السعر، والتوفر. السعر والتوفر يأتيان من منتج اللغة المصدر (نموذج المخزون المشترك).','Includes site name, url, and inLanguage.'=>'يشمل اسم الموقع، عنوان URL، و inLanguage.','Informative'=>'معلوماتي','Input tokens'=>'رموز الإدخال','Install'=>'تثبيت','Install a Language'=>'تثبيت لغة','Installed SEO plugins'=>'إضافات SEO المثبتة','Installing…'=>'جارٍ التثبيت…','instock / oos / pending from WC stock status'=>'متوفر في المخزون / غير متوفر / قيد الانتظار من حالة مخزون WC','Instructions (optional)'=>'تعليمات (اختياري)','Instructions / key points'=>'تعليمات / النقاط الرئيسية','Integration API'=>'واجهة برمجة التطبيقات للتكامل','Internal Link Fixer'=>'مصلح الروابط الداخلية','Introduction only'=>'مقدمة فقط','Invalid API key — double-check the key entered in the AI Provider settings.'=>'مفتاح API غير صالح — تحقق من المفتاح المدخل في إعدادات مزود الذكاء الاصطناعي.','Invalid file reference.'=>'مرجع ملف غير صالح.','Invalid filename.'=>'اسم ملف غير صالح.','Invalid language code.'=>'رمز اللغة غير صالح.','Invalid language.'=>'اللغة غير صالحة.','Invalid locale code.'=>'رمز اللغة غير صالح.','Invalid or primary language.'=>'اللغة غير صالحة أو أساسية.','Invalid post ID.'=>'معرف المنشور غير صالح.','Invalid post type.'=>'نوع المنشور غير صالح.','Invalid template part.'=>'جزء القالب غير صالح.','Invalid template type.'=>'نوع القالب غير صالح.','JavaScript-powered actions'=>'إجراءات تعتمد على JavaScript','Just now'=>'الآن فقط','Key points, ideas, or structure to build from…'=>'نقاط رئيسية، أفكار، أو هيكل للبناء عليه…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'يتم تشفير المفاتيح باستخدام AES-256-CBC قبل تخزينها في قاعدة بيانات ووردبريس. يتم اشتقاق سر التشفير من ملح المصادقة الخاص بك في ووردبريس (wp-config.php)، لذلك المفاتيح النصية العادية لا تلمس قاعدة البيانات.','Landing / Short-form'=>'صفحة هبوط / صيغة قصيرة','Language'=>'اللغة','Language %s installed successfully.'=>'تم تثبيت لغة %s بنجاح.','Language (optional)'=>'اللغة (اختياري)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'تم تعطيل تثبيت اللغة على هذا الخادم (تم تعيين DISALLOW_FILE_MODS).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'تم تعطيل تثبيت اللغة على هذا الخادم. تم تعيين الثابت DISALLOW_FILE_MODS في wp-config.php. قم بتثبيت حزم اللغات يدويًا عبر WP-CLI: wp language core install de_DE','Language label'=>'علامة اللغة','Language Overrides'=>'تجاوزات اللغة','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'تجاوزات اللغة: إدارة ملفات تجاوز .po/.mo المخصصة لنصوص واجهة مستخدم Lingua Forge. استخدم هذا بدلاً من تحرير ملفات الإضافة مباشرة — تظل التجاوزات بعد التحديثات.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'فشل تثبيت حزمة اللغة. قد تكون اللغة مثبتة بالفعل، أو قد يكون رمز اللغة غير صحيح، أو قد يمنع الخادم كتابة الملفات.','Language Setup'=>'إعداد اللغة','Language Switcher'=>'مبدل اللغة','Language switcher'=>'مفتاح التبديل اللغوي','Language uninstalled. %d post deleted.'=>'تم إلغاء تثبيت اللغة. تم حذف %d منشور.' . "\0" . 'تم إلغاء تثبيت اللغة. تم حذف %d منشورات.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'نسخ خاصة باللغة من أجزاء قالب السمة. بمجرد إنشائها، يتم تحديث القوالب للإشارة إلى الجزء الخاص باللغة.','Language:'=>'اللغة:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'اللغات المعروفة حاليًا للموجه (مشتقة من حزم اللغة المثبتة في ووردبريس بالإضافة إلى اللغة الأساسية). قم بتثبيت حزم لغوية إضافية في القسم أدناه لجعل المزيد من اللغات متاحة للتوجيه والترجمة.','Last 30 days'=>'آخر 30 يومًا','Last 7 days'=>'آخر 7 أيام','Last generated: %s'=>'تم الإنشاء آخر مرة: %s','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'أحدث درجة تحسين محركات البحث القائمة على القواعد. قم بتشغيل التحليل في الإعدادات → تحسين محركات البحث → التحليل للتحديث.','Last run: %s ago'=>'آخر تشغيل: منذ %s','Lead paragraph (≤60 w)'=>'الفقرة الافتتاحية (≤60 كلمة)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'اترك حقل النموذج فارغًا لاستخدام النموذج الافتراضي المدمج لهذا المستوى. يظهر نص العنصر النائب النموذج الذي سيتم استخدامه.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'اتركه فارغًا لأسماء العلامات التجارية والمصطلحات غير المرتبطة باللغة والتي يجب تطبيقها بغض النظر عن اللغة التي نترجم منها.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'اتركه فارغًا لتطبيق هذا الإدخال على جميع اللغات الهدف — مثالي لأسماء العلامات التجارية، الاختصارات، والمصطلحات التي يجب أن تُحفظ حرفيًا في كل ترجمة.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'اتركه فارغًا للحفاظ على المفتاح الحالي. أدخل قيمة جديدة لاستبداله.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'اتركه فارغًا لاستخدام الإعداد الافتراضي المدمج. استعادة تجاوز محفوظ يعيد التعيين إلى الافتراضي عند الحفظ التالي.','Legacy lf-social-share mu-plugin'=>'إضافة قديمة لـ lf-social-share mu-plugin','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'تم اكتشاف إضافة قديمة لـ lf-social-share mu-plugin. يؤجل LF مجموعة OG الأساسية إلى الإضافة ويصدر فقط og:locale و og:locale:alternate. يمكنك إلغاء تفعيل الإضافة — تغطي مشاركة الوسائط الاجتماعية المدمجة في LF (علامة التبويب SEO → مشاركة الوسائط الاجتماعية) وغطاء Open Graph نفس الوظيفة.','Legacy post-based (CPT)'=>'مستندات قديمة تعتمد على المنشور (CPT)','Legal / Compliance'=>'قانوني / امتثال','Legal / Compliance instructions'=>'تعليمات قانونية / امتثال','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'يضيف LF دائمًا og:locale و og:locale:alternate — إشارات OG متعددة اللغات التي لا يمكن لأي إضافة عامة لـ SEO إنتاجها بشكل صحيح. بالنسبة لمجموعة OG الأساسية (og:title، og:description، og:image)، يخرجها LF عندما لا توجد إضافة أخرى. عندما يتم تثبيت إضافة SEO، يتخطى LF المجموعة الأساسية لتجنب العلامات المكررة — ليس لأن الإضافة "أفضل"، ولكن لأن التكرار لا يضيف قيمة.','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'ينشئ LF خريطة موقع خاصة به مع روابط xhtml:link لمجموعات الترجمة. عندما يتم تثبيت إضافة SEO، يتم إنشاء خريطة موقع منفصلة — كلاهما يتعايش بشكل مستقل. قدم كلاهما إلى Google Search Console: خريطة الموقع الخاصة بـ SEO لاكتشاف المحتوى، وخريطة موقع LF لإشارات علاقة اللغة.','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'يصدر LF علامات hreflang وقد أزال وسم canonical الخاص بـ WordPress على الصفحات متعددة اللغات.','LF is suppressing hreflang output from: %s'=>'يقوم LF بكتم إخراج hreflang من: %s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'تُصدر LF علامات hreflang دقيقة لكل لغة مكونة، بما في ذلك x-default. لا تمتلك إضافات تحسين محركات البحث العامة وصولاً إلى تكوين توجيه LF الخاص بك، وستنتج علامات hreflang بناءً على افتراضات URL غير صحيحة. تقوم LF بكتم صوت مخرجاتها عبر مرشح لمنع التصادمات.','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'تُصدر LF JSON-LD متعدد اللغات مع تعليقات inLanguage المرتبطة بتكوين توجيه اللغة الخاص بها. عند تثبيت إضافة SEO، تقوم LF بتعطيل مخططها الخاص تمامًا: تتسبب تكرارات رسومات JSON-LD في أخطاء التحقق ولا توجد طريقة نظيفة لتكملة رسم بياني موجود.','LF provides'=>'تقدم LF','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'تزيل LF الوسم canonical الخاص بنواة WordPress على الصفحات متعددة اللغات لأن قواعد إعادة الكتابة التي تحتوي على بادئة اللغة في الموجه و hreflang x-default هي الإشارات canonical الصحيحة لموقع متعدد اللغات. هذا يمنع وجود canonical مزدوج إذا كانت إضافة SEO أيضًا تنتج واحدًا. لا تضيف LF canonical خاص بها — فتوثيق اللغة يجعل كل عنوان URL canonical بالفعل.','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'المدخلات المملوكة لـ LF مسجلة حاليًا في $wp_rewrite->extra_rules_top. مفيد لتشخيص أخطاء 404 أو تعارضات التوجيه. انسخ هذه عند تقديم تقرير عن خطأ.','Light'=>'خفيف','Light (default — fast and cost-effective)'=>'خفيف (افتراضي — سريع وفعال من حيث التكلفة)','Light (fast and cost-effective — Haiku / Flash)'=>'خفيف (سريع وفعال من حيث التكلفة — Haiku / Flash)','Light model'=>'نموذج خفيف','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'خفيف: يستخدم لوصف الميتا وتوليد المقتطفات — سريع، منخفض التكلفة.','Limit results to pages in the given Lingua Forge language code.'=>'تحديد النتائج لصفحات ضمن رمز لغة لينغوا فورج المحدد.','Limits'=>'الحدود','Lingua Forge'=>'لينجوا فورج','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'يضيف Lingua Forge التوجيه متعدد اللغات، الترجمة المدعومة بالذكاء الاصطناعي، علامات SEO hreflang، ومفتاح التبديل اللغوي إلى موقع WordPress الخاص بك.','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'تضيف Lingua Forge خصائص Open Graph الخاصة بـ WooCommerce إلى صفحات المنتجات بحيث يعرض مشاركة عنوان URL للمنتج على Facebook و Pinterest ومنصات مماثلة نوع المنتج الصحيح، السعر، والتوفر.','Lingua Forge AI Tools'=>'أدوات لينجوا فورج للذكاء الاصطناعي','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'توسع Lingua Forge كتلة رموز التواصل الاجتماعي في WordPress مع روابط مشاركة ديناميكية. قم بضبط رابط أي أيقونة إلى قيمة "share:"، وتقوم LF بإعادة كتابته إلى عنوان URL للمشاركة الصحيح أو إجراء JavaScript عند العرض — لا حاجة لرمز مخصص أو إضافة طرف ثالث.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'تولد Lingua Forge خريطة موقع XML مخصصة على /lf-sitemap.xml تضيف روابط بديلة للغة لجميع المحتوى المترجم الخاص بك. تكمل هذه الخريطة خريطة موقع WordPress الأساسية وأي خريطة موقع لإضافة SEO — فهي لا تحل محلها.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'تعد Lingua Forge حلاً كاملاً لتحسين محركات البحث متعدد اللغات. لا حاجة إلى إضافة SEO إضافية.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'تعد Lingua Forge حلاً كاملاً لتحسين محركات البحث متعدد اللغات. لا حاجة إلى إضافة SEO أو إضافة خريطة موقع إضافية.','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'تُصدر Lingua Forge علامات <link rel="alternate" hreflang> لكل لغة مكونة على كل صفحة، بما في ذلك x-default التي تشير إلى اللغة المصدر. هذه هي الإشارة الأساسية لتحسين محركات البحث متعددة اللغات لجوجل ومحركات البحث الأخرى — لا حاجة إلى مكون إضافي لتحسين محركات البحث.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'تُصدر Lingua Forge علامات ميتا Open Graph وTwitter Card بحيث تعرض عناوين URL المشتركة اللغة الصحيحة، العنوان، الوصف، والصورة على منصات التواصل الاجتماعي.','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'تُصدر Lingua Forge بيانات منظمة JSON-LD من Schema.org بحيث تفهم محركات البحث نوع المحتوى، اللغة، والبيانات الوصفية الخاصة بك. هذه هي الطريقة الأساسية للتواصل فيAnnotations inLanguage لمحتوى متعدد اللغات إلى Google ومراقبي الويب الآخرين.','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'يقيد Lingua Forge ميزتين من Gutenberg بشكل افتراضي للحفاظ على اتساق السلوك التحريري عبر اللغات. اختر هنا عندما تحتاج إلى قدرات كاملة لـ Gutenberg / FSE.','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'تحدد Lingua Forge نطاقات استعلامات WP_Query الثانوية (ويدجات الشريط الجانبي، كتل القوالب، استعلامات الإضافات) إلى اللغة النشطة عن طريق إدراج قيد ميتا _lf_lang. أنواع المنشورات المدرجة هنا مستبعدة من هذا القيد — استعلاماتها دائمًا غير مفلترة.','Lingua Forge Settings'=>'إعدادات Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'يستخدم Lingua Forge طبقتين مستقلتين من التخزين المؤقت لتجنب استدعاءات API المكررة للذكاء الاصطناعي. استخدم علامات التبويب أدناه لفحص وإدارة كل واحدة.','Lingua Forge uses two model tiers per provider:'=>'يستخدم Lingua Forge مستويين من النماذج لكل مزود:','Lingua Forge version'=>'إصدار Lingua Forge','Lingua Forge — Quick Translate'=>'لينجوا فورج — الترجمة السريعة','Lingua Forge — Settings'=>'لينغا فورج — الإعدادات','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'يغطي وحدات المشاركة الاجتماعية المدمجة في Lingua Forge وOpen Graph كل الوظائف التي يوفرها مكون MU، بالإضافة إلى دعم og:locale متعدد اللغات. يمكنك إيقاف تفعيل مكون MU بأمان.','Link copied'=>'تم نسخ الرابط','link(s)'=>'رابط(روابط)','Links'=>'روابط','Load available languages'=>'تحميل اللغات المتاحة','Load content'=>'تحميل المحتوى','Loaded from cache.'=>'تم التحميل من التخزين المؤقت.','Loading…'=>'جارٍ التحميل…','Locale only'=>'اللغة فقط','Locked — a conflicting SEO plugin is active. See the notice above.'=>'مغلق — مكون SEO متضارب نشط. راجع الإشعار أعلاه.','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'يخزن Loco Translate ترجماته المخصصة في wp-content/languages/loco/ — وهو موقع يمكن أن يتم مسحه بصمت بواسطة تحديث نواة ووردبريس، إعادة تثبيت الإضافة، أو إذا تمت إزالة Loco Translate نفسه. نسخ الملفات هنا ينقلها إلى دليل Lingua Forge i18n-overrides، الذي يستمر خلال جميع تلك الأحداث ويُحمّل تلقائيًا في كل طلب.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — النسخ إلى التخزين الآمن','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'أدنى قدرة في ووردبريس مسموح بها لتفعيل ميزات الذكاء الاصطناعي. تضييق هذا على مواقع متعددة المؤلفين يمنع المساهمين أو الحسابات التجريبية من تشغيل مكالمات الذكاء الاصطناعي المدفوعة. تجاوز حسب الميزة عبر مرشح `linguaforge_required_capability`.','Maintenance'=>'الصيانة','Maintenance Tab'=>'علامة التبويب الصيانة','Make casual'=>'اجعله غير رسمي','Make concise'=>'اجعله موجزًا','Make formal'=>'اجعله رسميًا','Manage your account, review usage, or top up credits:'=>'إدارة حسابك، مراجعة الاستخدام، أو تعبئة الرصيد:','Mark citations needed'=>'علامة على الحاجة إلى اقتباسات','Max context characters'=>'أقصى عدد أحرف للسياق','Max hints characters'=>'أقصى عدد أحرف للتلميحات','Max input characters'=>'عدد الأحرف المدخلة القصوى','Max output tokens'=>'الحد الأقصى لعدد الرموز الناتجة','Maximum characters accepted from the input field. Default: 8 000.'=>'الحد الأقصى لعدد الأحرف المقبولة من حقل الإدخال. الافتراضي: 8000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'الحد الأقصى لعدد الأحرف لمحتوى المنشور الموجود الممرر إلى الذكاء الاصطناعي كالسياق البذري عند عدم تقديم تلميحات. الافتراضي: 6000.','Maximum characters read from the Hints field. Default: 2 000.'=>'الحد الأقصى لعدد الأحرف المقروءة من حقل التلميحات. الافتراضي: 2000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'الحد الأقصى لعدد الأحرف لمحتوى المنشور الموجه إلى الذكاء الاصطناعي. 0 يعني عدم وجود حد — يتم دائمًا إرسال المحتوى الكامل (موصى به). اضبط قيمة غير صفرية فقط إذا كان مزود الخدمة الخاص بك لديه نافذة سياق ضيقة. يتم كتابة تحذير في سجل أخطاء PHP كلما تم تقليم المحتوى.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'الحد الأقصى لعدد الرموز التي يمكن للذكاء الاصطناعي إنتاجها في استجابة ترجمة واحدة. إذا تم قطع الترجمة بصمت في النهاية، قم بزيادة هذه القيمة. الافتراضي: 16000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'الحد الأقصى للرموز التي قد ينتجها الذكاء الاصطناعي لكل عملية توليد. زد هذا إذا تم قطع المقالات الكاملة. الافتراضي: 8192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'الحد الأقصى للرموز التي قد ينتجها الذكاء الاصطناعي لكل ترجمة سريعة. الافتراضي: 2000.','Meta Description'=>'وصف ميتا','Meta description'=>'الوصف التعريفي','Meta Description, Excerpt Generator'=>'وصف ميتا، مولد المقتطفات','Meta Description, Excerpt Generator, quick translate'=>'الوصف التعريفي، منشئ المقتطفات، الترجمة السريعة','Metric'=>'مقياس','Minimum role'=>'الدور الأدنى','Missing'=>'مفقود','Missing pattern name or language.'=>'اسم النمط أو اللغة مفقود.','Mode'=>'الوضع','Model'=>'النموذج','Model ID'=>'معرف النموذج','Model tier'=>'طبقة النموذج','Models'=>'نماذج','Models Tab (General)'=>'علامة التبويب النماذج (عام)','Modified'=>'تم التعديل','Most recent cached block'=>'الكتلة المخزنة مؤخرًا','Most recent cached response'=>'الاستجابة المخزنة مؤخرًا','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'توجيه متعدد اللغات، تحسين محركات البحث متعدد اللغات بالكامل (hreflang، Open Graph، Schema.org، خريطة الموقع)، وأدوات محتوى الذكاء الاصطناعي لـ ووردبريس. اكتشاف اللغة، توجيه URL، الترجمة، إنشاء المحتوى، وطبقة SEO كاملة — لا حاجة إلى مكون إضافي مرافق.','Multilingual SEO'=>'تحسين محركات البحث متعددة اللغات','Multilingual SEO overview'=>'نظرة عامة على تحسين محركات البحث متعددة اللغات','My Account'=>'حسابي','Name'=>'الاسم','Name displayed in this language. Leave empty to use the source name.'=>'الاسم المعروض بهذه اللغة. اتركه فارغًا لاستخدام الاسم المصدر.','Navigation'=>'التنقل','Navigation has no content to translate.'=>'لا يوجد محتوى للتنقل لترجمته.','Navigation not found.'=>'لم يتم العثور على التنقل.','Navigation posts are translated via the Router tab, not this button.'=>'يتم ترجمة منشورات التنقل عبر علامة التبويب Router، وليس هذا الزر.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'يتطلب ترجمة التنقل وجود مزود ذكاء اصطناعي نشط. قم بتكوين مفتاح API في علامة تبويب مفاتيح API.','Navigations'=>'التنقلات','Network error — could not reach the provider: %s'=>'خطأ في الشبكة — تعذر الوصول إلى المزود: %s','Network error — could not reach the WordPress AJAX endpoint.'=>'خطأ في الشبكة — تعذر الوصول إلى نقطة نهاية WordPress AJAX.','Network error.'=>'خطأ في الشبكة.','Never run'=>'لا تتشغل أبدًا','No %s version found in this translation group.'=>'لم يتم العثور على إصدار %s في مجموعة الترجمات هذه.','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'لا حاجة لاتخاذ إجراء. قامت Google بإيقاف نقطة نهاية ping لخريطة الموقع في يناير 2024، وتكتشف الآن خريطة الموقع حصريًا عبر توجيه Sitemap في robots.txt — والذي قامت LF بتكوينه بالفعل. ستلتقطها Google عند الزحف التالي.','No active plugins detected.'=>'لم يتم اكتشاف أي إضافات نشطة.','No AI provider configured.'=>'مزود الذكاء الاصطناعي غير مهيأ.','No AI provider configured. Add an API key in Settings → API Keys.'=>'لم يتم تكوين مزود AI. أضف مفتاح API في الإعدادات → مفاتيح API.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'لم يتم تسجيل استخدام للذكاء الاصطناعي في النافذة المختارة (%s). اختر نطاقًا أوسع أعلاه.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'لم يتم تسجيل استخدام للذكاء الاصطناعي بعد. بمجرد أن يقوم محرر بتشغيل ترجمة، أو إنشاء وصف ميتا، أو استخدام أي ميزة أخرى للذكاء الاصطناعي، ستظهر الإجماليات هنا.','No API key configured for this provider.'=>'لا يوجد مفتاح API مهيأ لهذا المزود.','No API key configured — enter your key in the AI Provider settings.'=>'لم يتم تكوين مفتاح API — أدخل مفتاحك في إعدادات مزود الذكاء الاصطناعي.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'لا توجد تعليمات مدمجة — كل ميزة AI تستخدم إعداداتها الافتراضية الخاصة. املأ حقل تعليمات المطالب المخصصة أدناه لإضافة قواعد موقعك الخاصة.','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'لم يتم اكتشاف إضافات SEO متضاربة. تتولى Lingua Forge إدارة جميع مخرجات SEO بشكل مستقل.','No credits remaining — top up your OpenAI account at platform.openai.com/account/billing.'=>'لا توجد أرصدة متبقية — قم بتعبئة حساب OpenAI الخاص بك على platform.openai.com/account/billing.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'لم يتم العثور على ملفات Loco Translate مخصصة بعد. تظهر هنا بمجرد حفظ ترجمة في Loco Translate.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'لم يتم اكتشاف مكون OG خارجي. تقوم LF بإخراج مجموعة OG + Twitter Card الكاملة.','No file was selected.'=>'لم يتم اختيار أي ملف.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'لا تتطابق إدخالات المصطلح مع التصفية الحالية. قم بمسح التصفية لرؤية جميع الإدخالات، أو أضف إدخالًا جديدًا أدناه.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'لا توجد إدخالات مصطلح بعد. أضف واحدًا أدناه لبدء تطبيق المصطلحات في الترجمات.','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'لم يتم العثور على H1. عادةً يكون عنوان المنشور هو H1 — تحقق من أن السمة الخاصة بك تقوم بإخراجه.','No images found in content.'=>'لم يتم العثور على صور في المحتوى.','No internal links found to update.'=>'لم يتم العثور على روابط داخلية للتحديث.','No key'=>'لا مفتاح','No language-specific template parts found to map.'=>'لم يتم العثور على أجزاء قالب محددة للغة لتعيينها.','No LF meta description set — using excerpt/content.'=>'لم يتم تعيين وصف ميتا لـ LF — يتم استخدام المقتطف / المحتوى.','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'لم يتم العثور على قواعد إعادة كتابة LF. قم بمسح الروابط الدائمة إذا كان هذا غير متوقع.','No links found.'=>'لم يتم العثور على روابط.','No links found. Internal links improve crawlability and user navigation.'=>'لم يتم العثور على روابط. الروابط الداخلية تحسن قابلية الزحف وتصفح المستخدم.','No meta description found. Generate one via the AI meta description feature.'=>'لم يتم العثور على وصف ميتا. أنشئ واحدًا عبر ميزة الوصف الميتا بواسطة AI.','No navigation references needed updating.'=>'لا حاجة لتحديث مراجع التنقل.','No override files uploaded yet.'=>'لم يتم تحميل ملفات تجاوز بعد.','No PHP limit'=>'لا حد لبايثون','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'لم يتم العثور على ملف robots.txt فعلي. يقوم WordPress بإنشائه افتراضيًا، وتوجيه Sitemap الخاص بـ LF مضمّن تلقائيًا.','No published posts found for the selected filters.'=>'لم يتم العثور على منشورات منشورة للمرشحات المختارة.','No response from AI provider. Check your API key and try again.'=>'لم يتلقَ رد من مزود AI. تحقق من مفتاح API الخاص بك وحاول مرة أخرى.','No response from provider — check the error log for details.'=>'لا استجابة من المزود — تحقق من سجل الأخطاء للتفاصيل.','No secondary languages configured.'=>'لم يتم تكوين لغات ثانوية.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'لم يتم تكوين لغات ثانوية. قم بتثبيت حزمة لغة أعلاه لتمكين إنشاء القوالب.','No source content found to translate.'=>'لم يتم العثور على محتوى مصدر لترجمته.','No source page linked yet.'=>'لم يتم ربط صفحة المصدر بعد.','No template part references needed updating.'=>'لا حاجة لتحديث مراجع أجزاء القالب.','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'لم يتم اكتشاف إضافات SEO من طرف ثالث. Lingua Forge يتعامل مع جميع مخرجات SEO متعددة اللغات.','No title set.'=>'لم يتم تعيين عنوان.','No translated content found. The sitemap will populate once posts have been translated.'=>'لم يتم العثور على محتوى مترجم. ستملأ خريطة الموقع بمجرد ترجمة المنشورات.','No translation found — analyzed the source language version.'=>'لم يتم العثور على ترجمة — تم تحليل نسخة اللغة المصدر.','No {lang} translation registered (TRID missing)'=>'لم يتم تسجيل ترجمة {lang} (TRID مفقود)','No — WooCommerce integration class not loaded'=>'لم يتم تحميل فئة تكامل WooCommerce','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'لم يتم إنشاؤه بعد. يتم بناء خريطة الموقع عند الزيارة الأولى لعنوان URL الخاص بخريطة الموقع وتخزينها مؤقتًا لمدة 24 ساعة.','Notes'=>'ملاحظات','Nothing — all types disabled'=>'لا شيء — تم تعطيل جميع الأنواع','Notice message'=>'رسالة الإشعار','Notice settings'=>'إعدادات الإشعار','Notify search engines'=>'إعلام محركات البحث','Numeric permalink structure is not supported.'=>'هيكل الرابط الدائم الرقمي غير مدعوم.','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'علامات OG/Twitter Card: تتم معالجتها بواسطة وحدة Open Graph الخاصة بـ LF (SEO → Open Graph & Twitter Cards)','Oldest cached block'=>'الكتلة الأقدم المخزنة','Oldest cached response'=>'الاستجابة الأقدم المخزنة','Only .mo files are accepted.'=>'فقط ملفات .mo مقبولة.','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'بطاقات Open Graph وتويتر','Open Graph output'=>'إخراج Open Graph','Open Graph settings saved.'=>'تم حفظ إعدادات Open Graph.','Open Search Console →'=>'فتح Search Console →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'افتح ورقة مشاركة الويب الأصلية للمتصفح (iOS، Android، بعض أجهزة الكمبيوتر). يرجع إلى النسخ إلى الحافظة إذا لم يكن مدعومًا.','OpenAI (GPT)'=>'OpenAI (GPT)','OpenAI Platform'=>'منصة OpenAI','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'السياق الاختياري للمحررين (مثل "ASIC = الدائرة المتكاملة الخاصة بالتطبيق؛ الحفاظ عليها باللغة الإنجليزية في السياقات التقنية").','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'اختياري. يقرأ Bing بالفعل توجيه Sitemap: من robots.txt — هذا فقط يطلق عملية إعادة الزحف الفورية بدلاً من الانتظار للفحص المجدول التالي.','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'اختياري. يقرأ Yandex بالفعل توجيه Sitemap: من robots.txt — هذا فقط يطلق عملية إعادة الزحف الفورية بدلاً من الانتظار للفحص المجدول التالي.','Order storage'=>'تخزين الطلبات','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'الطلبات في wp_posts — تأكد من استبعاد shop_order من التوجيه LF.','Output'=>'مخرجات','Output Article or WebPage schema on singular posts and pages'=>'إخراج مخطط Article أو WebPage على المنشورات والصفحات المفردة','Output hreflang tags in wp_head'=>'إخراج علامات hreflang في wp_head','Output mode'=>'وضع الإخراج','Output Open Graph tags in wp_head'=>'إخراج علامات Open Graph في wp_head','Output Product schema on WooCommerce product pages'=>'إخراج مخطط المنتج على صفحات منتجات WooCommerce','Output Schema.org JSON-LD in wp_head'=>'مخطط JSON-LD الخاص بـ Schema.org في wp_head','Output tokens'=>'رموز الإخراج','Output WebSite schema on the front page and blog index'=>'إخراج مخطط الموقع على الصفحة الرئيسية وفهرس المدونة','Overall SEO score'=>'مجموع درجة تحسين محركات البحث','overridden'=>'تم تجاوزها','Override file deleted.'=>'تم حذف ملف التجاوز.','Override file uploaded successfully.'=>'تم تحميل ملف التجاوز بنجاح.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'يتجاوز إعداد الذكاء الاصطناعي للترجمة وتوليد المحتوى في هذه الصفحة. تستخدم جميع الميزات الأخرى دائمًا الإعداد الافتراضي العالمي.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'يتجاوز إعداد الذكاء الاصطناعي للترجمة وتوليد المحتوى في هذه الصفحة. دائمًا ما يتم إلحاق تعليمات الموجه المخصصة على مستوى الموقع (الإعدادات → السلوك) بكل طلب بغض النظر عن هذا الاختيار.','Overview'=>'نظرة عامة','Page'=>'صفحة','Part'=>'جزء','Paste a footnote, sentence, or any snippet here…'=>'الصق حاشية، جملة، أو أي مقتطف هنا…','Paste text, or select text in the editor first…'=>'الصق النص، أو حدد النص في المحرر أولاً…','Paste text, or select text on the page first…'=>'الصق النص، أو حدد النص على الصفحة أولاً…','Paste your API key…'=>'الصق مفتاح API الخاص بك…','Path prefix (/de/)'=>'بادئة المسار (/de/)','Path prefix — example.com/de/'=>'بادئة المسار — example.com/de/','Path routing requires a post-name based permalink structure. Change it in'=>'تتطلب توجيه المسار هيكل رابط دائم يعتمد على اسم المنشور. قم بتغييره في','Pattern'=>'نمط','Pattern has no content to translate.'=>'النمط لا يحتوي على محتوى للترجمة.','Pattern not found.'=>'لم يتم العثور على النمط.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'تم ترجمة النمط وحفظه. انسخ المحتوى إلى منشور CPT الخاص بك عبر أداة إدراج الأنماط في محرر الكتل أو استخدمه كنقطة انطلاق لكتلة قابلة لإعادة الاستخدام.','Pattern translation failed.'=>'فشلت ترجمة النمط.','Payment required — your account has no remaining credits.'=>'مطلوب الدفع — حسابك لا يملك أرصدة متبقية.','Per-Post Analysis'=>'تحليل لكل منشور','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'ذاكرة مؤقتة لكل منشور للترجمات التي يتم إنشاؤها بواسطة الذكاء الاصطناعي، والأوصاف التعريفية، والمقتطفات، والمحتوى. يتم إبطال صلاحية الإدخالات تلقائيًا عند تغيير المحتوى أو مزود/نموذج الذكاء الاصطناعي.','Permalink rules flushed successfully.'=>'تم تفريغ قواعد الرابط الدائم بنجاح.','Permalink Structure'=>'هيكل الرابط الدائم','Permalink structure is compatible with Lingua Forge path routing.'=>'هيكل الرابط الدائم متوافق مع توجيه مسار Lingua Forge.','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'يحذف نهائيًا جميع القوالب، أجزاء القالب، الأنماط، قوائم التنقل، المنشورات، الصفحات، أنواع المنشورات المخصصة، المنتجات، وتنوعات المنتجات المرتبطة بهذه اللغة. كما يزيل ملفات حزمة اللغة الخاصة بووردبريس بحيث لم تعد تظهر في الموجه. لا يمكن التراجع عن هذا الإجراء.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'هل تريد إلغاء تثبيت %s بشكل دائم؟ هذا سيحذف جميع المحتوى المترجم لهذه اللغة ولا يمكن التراجع عنه.','Permission denied.'=>'تم رفض الإذن.','Persuasive'=>'إقناعي','PHP constant'=>'ثابت PHP','PHP max_execution_time'=>'الحد الأقصى لوقت تنفيذ PHP','PHP memory_limit'=>'حدود ذاكرة PHP','PHP version'=>'إصدار PHP','Pin on Pinterest'=>'ثبّت على Pinterest','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'تثبيت المصطلحات التي يجب عدم ترجمتها أو التي يجب دائمًا عرضها بطريقة معينة (مثل أسماء العلامات التجارية، أسماء المنتجات، الاختصارات). يتم حقن قيود القاموس في كل طلب ترجمة للذكاء الاصطناعي لجميع الميزات: ترجمة المنشور، الوصف التعريفي، المقتطف، وترجمة قالب FSE.','Ping Bing'=>'إشارة إلى Bing','Ping Yandex'=>'إشارة إلى Yandex','Plain language'=>'لغة بسيطة','Plain permalinks are not supported.'=>'الروابط الدائمة البسيطة غير مدعومة.','Please enter some instructions first…'=>'يرجى إدخال بعض التعليمات أولاً…','Please enter some text first…'=>'يرجى إدخال بعض النصوص أولاً…','Plugin'=>'إضافة','Post'=>'منشور','Post not found or not published.'=>'لم يتم العثور على المنشور أو لم يُنشر بعد.','Post not found.'=>'المنشور غير موجود.','Post on X / Twitter'=>'منشور على X / تويتر','Post type'=>'نوع المنشور','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'الأنواع المميزة للمنشورات مفصولة بفواصل أو أسطر جديدة. التغييرات تأخذ مفعولها فور الحفظ — لا حاجة لتحديث الرابط الدائم.','Post Types'=>'أنواع المنشورات','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'المنشورات بدون _lf_lang غير مرئية لكل مرشح لغة من Lingua Forge. يمكن أن يحدث هذا عند استيراد المحتوى أو إنشائه قبل تفعيل الإضافة.','Prefilled from excerpt. Edit to override.'=>'مملوء مسبقًا من المقتطف. عدل للتجاوز.','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'السعر والتوافر يعكسان دائمًا المنتج باللغة المصدر (نموذج المخزون المشترك). يتم إخراج العلامات فقط عندما يكون وضع Open Graph الخاص بـ LF مضبوطًا على "كامل" أو "تلقائي" بدون اكتشاف مكون SEO متضارب.','Primary content language'=>'لغة المحتوى الأساسية','Primary Language'=>'اللغة الأساسية','Primary language'=>'اللغة الأساسية','Primary language saved.'=>'تم حفظ اللغة الأساسية.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'اللغة الأساسية: اللغة التي كتب بها المحتوى الحالي الخاص بك. يتم إنتاج جميع الترجمات من هذه اللغة؛ تغييرها لا ينقل أو يحذف أي منشورات.','Processing…'=>'جار المعالجة…','Product'=>'منتج','Product / eCommerce'=>'منتج / التجارة الإلكترونية','Product Open Graph'=>'Open Graph للمنتج','Product — WooCommerce product pages'=>'منتج — صفحات منتجات WooCommerce','Profile'=>'الملف الشخصي','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'تتكيف الملفات الشخصية مع العتبات والأوزان لنوع المحتوى الذي يتم تحليله. يتم حل الملف الشخصي تلقائيًا؛ يمكنك تعديله لكل عملية تحليل من قائمة اختيار الملف الشخصي.','Provider'=>'المزود','Provider error (HTTP %1$d): %2$s'=>'خطأ المزود (HTTP %1$d): %2$s','Provider returned no response. Check the WordPress error log for details.'=>'لم يُرجع المزود استجابة. تحقق من سجل أخطاء ووردبريس للتفاصيل.','Provider service temporarily unavailable — try again in a moment.'=>'خدمة المزود غير متاحة مؤقتًا — حاول مرة أخرى بعد قليل.','Quality'=>'جودة','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'الجودة (افتراضي — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'الجودة (سونيت / GPT-4o / جمنى برو)','Quality model'=>'نموذج الجودة','Quality: used for post translation and content generation — higher quality, higher cost.'=>'الجودة: تستخدم لترجمة المنشورات وتوليد المحتوى — جودة أعلى، تكلفة أعلى.','Query Filter Exclusions'=>'استثناءات مرشح الاستعلام','Quick Translate'=>'ترجمة سريعة','Quick Translation'=>'ترجمة سريعة','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'تُستخدم الترجمة السريعة في وضع المقتطف / القطعة — ترجمات قصيرة يتم طلبها عند الحاجة من شريط الأدوات أو المحرر أو نوافذ النقر على الكتل. تستخدم تكوينًا منفصلًا وأخف من ترجمة الصفحة الكاملة للحفاظ على سرعة الاستجابة وتقليل التكاليف.','Rate limited — too many requests sent to the provider; wait a moment and try again.'=>'محدد المعدل — تم إرسال العديد من الطلبات إلى المزود؛ انتظر لحظة وحاول مرة أخرى.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'يعيد تفعيل canLockBlocks الخاص بـ Gutenberg. مفيد لنماذج التحرير التي تحتاج إلى منع المساهمين من نقل أو حذف كتل معينة.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'يعيد تفعيل supportsTemplateMode. أساسي لعمليات تحرير الموقع الكامل حيث تكون تجاوزات النموذج على مستوى المنشور مقصودة.','Re-generates and updates the cached result.'=>'يعيد التوليد ويحدث النتيجة المخزنة مؤقتًا.','Re-scan'=>'إعادة الفحص','Re-scanning…'=>'إعادة الفحص…','Re-translate'=>'إعادة الترجمة','Reading time'=>'وقت القراءة','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'إعادة توجيه الزوار إلى لغتهم المفضلة استنادًا إلى رأس Accept-Language الخاص بالمتصفح','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'تحسين أكثر — مثلاً "اجعله أقصر" أو "استخدم نغمة رسمية"…','Refine further:'=>'تحسين أكثر:','Refinement'=>'تحسين','Refinement failed — please try again.'=>'فشل التَّحسين — يرجى المحاولة مرة أخرى.','Refining…'=>'جارٍ التَّحسين…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'يعيد إنشاء قواعد إعادة كتابة ووردبريس بحيث تكون بادئات URL، والكلمات المفتاحية الخاصة باللغة، وإعادة كتابة الأرشيف متزامنة. ضروري بعد تغيير اللغة الأساسية أو إضافة دعم لغة جديدة.','Remove stored key'=>'إزالة المفتاح المخزن','Repair failed.'=>'فشل الإصلاح.','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'إصلاح العلامات لكل منشور قابل للتوجيه مدرج أعلاه مع _lf_lang = %s. المنشورات في أنواع المنشورات المستبعدة من التوجيه لا تتأثر. قم بتشغيل هذا فقط بعد استيراد المحتوى أو عند التفعيل الأول — لا تستخدمه كأداة لإعادة تعيين اللغة بشكل جماعي.','Repair — assign _lf_lang = %s to all routable posts above'=>'إصلاح — تعيين _lf_lang = %s لجميع المنشورات القابلة للتوجيه أعلاه','Repairing…'=>'جارٍ الإصلاح…','Report an issue on GitHub'=>'الإبلاغ عن مشكلة على GitHub','Request failed — please try again.'=>'فشل الطلب — يرجى المحاولة مرة أخرى.','Request failed.'=>'فشل الطلب.','Request failed. Check your connection.'=>'فشلت الطلب. تحقق من اتصالك.','Request failed. Please try again.'=>'فشلت الطلب. يرجى المحاولة مرة أخرى.','Requests'=>'الطلبات','requests / day'=>'طلبات / يوم','Reset'=>'إعادة تعيين','Result will appear here…'=>'سيظهر النتيجة هنا…','Retranslate'=>'إعادة الترجمة','Retranslating…'=>'جارٍ إعادة الترجمة…','Review carefully — links and slugs not updated.'=>'راجع بعناية — لم يتم تحديث الروابط والروابط المختصرة.','Review translation before applying'=>'مراجعة الترجمة قبل التطبيق','Revise'=>'راجع','Revision'=>'مراجعة','Revision Type'=>'نوع المراجعة','Rewrite Rules'=>'قواعد إعادة الكتابة','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'تم تحديث robots.txt مع توجيه Sitemap.','Router'=>'الموجه','Router Tab'=>'علامة التبويب الموجه','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'إجراء تدقيق كامل لتحسين محركات البحث عبر جميع المنشورات المنشورة لواحدة أو جميع اللغات النشطة. يتم حفظ النتائج لكل منشور وتظهر في شارات عمود اللغة في قائمة المنشورات.','Run AI Analysis'=>'تشغيل تحليل الذكاء الاصطناعي','Save'=>'حفظ','Save analysis settings'=>'حفظ إعدادات التحليل','Save Debug Setting'=>'حفظ إعداد التصحيح','Save Hreflang Settings'=>'حفظ إعدادات Hreflang','Save Open Graph Settings'=>'حفظ إعدادات Open Graph','Save Router Settings'=>'حفظ إعدادات الموجه','Save Schema.org Settings'=>'حفظ إعدادات Schema.org','Save Settings'=>'حفظ الإعدادات','Save Sitemap Settings'=>'حفظ إعدادات Sitemap','Save Social Share Settings'=>'حفظ إعدادات المشاركة الاجتماعية','Save the post to persist changes.'=>'احفظ المنشور للحفاظ على التغييرات.','Save Uninstall Setting'=>'حفظ إعداد إلغاء التثبيت','Save WooCommerce SEO Settings'=>'حفظ إعدادات تحسين محركات البحث لـ WooCommerce','Saved to the meta description field when you apply.'=>'تم حفظه في حقل وصف الميتا عند التطبيق.','Scan failed: '=>'فشل الفحص: ','Scan request failed. Please try again.'=>'فشل طلب الفحص. يرجى المحاولة مرة أخرى.','Scanning posts for broken language links…'=>'فحص المنشورات للروابط المكسورة…','Schema output deferred.'=>'تم تأجيل إخراج Schema.','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'JSON-LD الخاص بـ Schema.org','Schema.org output'=>'إخراج Schema.org','Schema.org settings saved.'=>'تم حفظ إعدادات Schema.org.','Score'=>'النتيجة','Score computation'=>'حساب النقاط','Score history and badges'=>'تاريخ النقاط والوسوم','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'النتائج إشارة، وليست حكمًا. بعض المحتوى محدود هيكليًا — صفحات قصيرة جدًا، صفحات هبوط تحتوي على نص قليل، أو صفحات هدفها التنقل بدلاً من المعلومات قد تحصل على درجات أقل بطبيعتها. استخدم هذا الملخص لاكتشاف فجوات التماثل الحقيقية عبر اللغات، وليس لملاحقة رقم.','Search'=>'بحث','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'مراقب البحث مفيد لمراقبة أخطاء الفهرسة والتغطية، لكنه غير مطلوب للاكتشاف.','Search Results'=>'نتائج البحث','Security check failed — file path is not permitted.'=>'فشل التحقق الأمني — مسار الملف غير مسموح به.','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'اطلع على الإعدادات → SEO → التوافقية للحصول على جدول سلوك كامل لكل ميزة.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'اختر لغة لإدارة قوالب FSE الخاصة بها، وأجزاء القالب، وقوائم التنقل.','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'اختر منشورًا وقم بإجراء تدقيق SEO مفصل لرؤية النتائج لكل مقياس ودرجة لذلك العنصر المحدد.','Select language'=>'اختر اللغة','Send via Telegram'=>'إرسال عبر Telegram','Send via WhatsApp'=>'إرسال عبر WhatsApp','SEO'=>'تحسين محركات البحث','SEO Analysis'=>'تحليل SEO','SEO character-count info'=>'معلومات عدد الأحرف لتحسين محركات البحث','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'تم اكتشاف مكون إضافي لـ SEO: %s. يقوم LF بإخراج og:locale و og:locale:alternate فقط؛ المكون الإضافي المكتشف يتعامل مع مجموعة OG الكاملة.','SEO Plugins'=>'إضافات SEO','SEO plugins and conflict avoidance:'=>'مكونات إضافية لـ SEO وتجنب التضارب:','SEO Score System'=>'نظام تقييم SEO','SEO Scores'=>'درجات SEO','SEO Tab'=>'علامة التبويب SEO','Server setup (subdomain)'=>'إعداد الخادم (النطاق الفرعي)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'يحدد السلوك الافتراضي للذكاء الاصطناعي لجميع الميزات على مستوى الموقع. يمكن للمنشورات الفردية تجاوز ذلك لخاصية الترجمة وتوليد المحتوى عبر مربع بيانات Lingua Forge.','Settings'=>'الإعدادات','Settings saved.'=>'تم حفظ الإعدادات.','Settings → Permalinks'=>'الإعدادات → الروابط الدائمة','Share on Facebook'=>'مشاركة على Facebook','Share on LinkedIn'=>'مشاركة على LinkedIn','Share on Mastodon'=>'مشاركة على Mastodon','Share via email (mailto:)'=>'مشاركة عبر البريد الإلكتروني (mailto:)','Shared / compatibility mode'=>'وضع المشاركة / التوافق','Shop'=>'متجر','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'المحتوى المختصر (3 فقرات أو أقل) لا يُعاقب على عدم وجود عناوين فرعية، بغض النظر عن الملف الشخصي. الصفحة المختصرة لا تستفيد من بنية العناوين المفروضة.','Show home link'=>'عرض رابط الصفحة الرئيسية','Shown when no translation exists for the visitor\'s language.'=>'تظهر عندما لا توجد ترجمة للغة الزائر.','Single'=>'مفرد','Single %s'=>'فرد %s','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'عنوان كلمة واحدة (%d أحرف) — إضافة كلمة ثانية يحسن الوضوح وتغطية الكلمات المفتاحية.','Single: %s'=>'فرد: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'السقف على مستوى الموقع لطلبات الذكاء الاصطناعي لكل يوم بالتوقيت العالمي المنسق (يشمل ترجمات شريط الأدوات ومراجعات الكتل). يعاد تعيين العداد عند منتصف الليل بالتوقيت العالمي المنسق. اضبطه على 0 لتعطيل الحد.','Sitemap'=>'خريطة الموقع','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'تم مسح ذاكرة التخزين المؤقت لخريطة الموقع. سيتم إعادة إنشائها عند الزيارة التالية لعنوان URL الخاص بخريطة الموقع.','Sitemap output'=>'إخراج خريطة الموقع','Sitemap settings saved.'=>'تم حفظ إعدادات خريطة الموقع.','Sitemap URL'=>'عنوان URL الخاص بخريطة الموقع','Size'=>'الحجم','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'مشاركة رموز التواصل الاجتماعي: عناوين URL: يتم التعامل معها بواسطة ميزة المشاركة الاجتماعية المدمجة في LF (SEO → المشاركة الاجتماعية)','Social Share'=>'مشاركة اجتماعية','Social Share settings saved.'=>'تم حفظ إعدادات المشاركة الاجتماعية','Some link fixes failed.'=>'فشلت بعض إصلاحات الروابط.','Some nav ref fixes failed.'=>'فشلت بعض إصلاحات مراجع التنقل.','Some part fixes failed.'=>'فشلت بعض إصلاحات الأجزاء.','Some parts could not be created.'=>'تعذر إنشاء بعض الأجزاء.','Some templates could not be created.'=>'تعذر إنشاء بعض القوالب.','Some translations failed.'=>'فشلت بعض الترجمات.','source'=>'المصدر','Source file not found.'=>'لم يتم العثور على الملف المصدر.','Source lang'=>'اللغة المصدر','Source language'=>'اللغة المصدر','Source term'=>'المصطلح المصدر','Source title'=>'عنوان المصدر','Standard'=>'افتراضي','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'يستخدم الوضع القياسي درجة حرارة مخصصة لكل ميزة: الترجمة T=0.2 (دقيق)، الترجمة السريعة T=0.4، مولد المحتوى T=0.6 (مبدع). تطبق الإعدادات المسبقة الأخرى درجة حرارة ثابتة واحدة عبر جميع الميزات.','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'ابدأ بالكتابة في أي حقل لرؤية اقتراحات النموذج، أو استخدم جدول المراجع أدناه. نماذج الجودة الخفيفة والمتوسطة (هايكو، GPT-4o ميني، Gemini Flash) كافية تمامًا للترجمة وتوليد المحتوى — نماذج "ماكس" الرائدة تضيف تكلفة مع فائدة جودة قليلة للنص المنظم.','Status'=>'الحالة','Status / Actions'=>'الحالة / الإجراءات','Storytelling'=>'سرد القصص','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'وضع الحفظ الصارم للمحتوى القانوني والتنظيمي والطبي أو التقني. عند التفعيل، يستخدم كل ميزة ذكاء اصطناعي درجة حرارة عينة منخفضة ويضيف الملحق أدناه إلى مطالبه النظامية — يتم الحفاظ على المصطلحات وأرقام المقالات والوحدات وأسماء العلامات التجارية واللغة التنظيمية حرفيًا بدلاً من إعادة صياغتها.','Structured Outline'=>'مخطط منظم','Subdomain (de.example.com)'=>'النطاق الفرعي (de.example.com)','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'يتطلب وضع النطاق الفرعي أن يشير خادم الويب الخاص بك إلى جميع النطاقات الفرعية للغة (مثل de.example.com) إلى تثبيت ووردبريس هذا. بعد تغيير الأوضاع، قم بمسح قواعد الروابط الثابتة وامسح أي ذاكرات مؤقتة. إذا كان عنوان URL الرئيسي الخاص بك يتضمن www (مثل www.example.com)، استخدم مرشح lf_base_domain لضبط النطاق الأساسي الخالي بحيث يتم إنشاء النطاقات الفرعية بشكل صحيح.','Subdomain — de.example.com/'=>'النطاق الفرعي — de.example.com/','Submit this URL to Google Search Console alongside your main sitemap.'=>'قدم عنوان URL هذا إلى Google Search Console جنبًا إلى جنب مع خريطة الموقع الرئيسية الخاصة بك.','Submit to Reddit'=>'قدم إلى Reddit','Suggested meta description'=>'وصف ميتا المقترح','Suggested title'=>'العنوان المقترح','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'مزودو الدعم: Anthropic (Claude)، OpenAI (GPT)، Google (Gemini). مزود واحد فقط نشط في وقت واحد. اختر المزود النشط في علامة التبويب العامة.','Suppressed: %s.'=>'تم كتمه: %s.','Switch to a post-name based structure in'=>'التبديل إلى هيكل يعتمد على اسم المنشور في','System'=>'النظام','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6، لكل ميزة','Tag'=>'علامة','Tags emitted'=>'تم إصدار العلامات','Target lang'=>'اللغة الهدف','Target Language'=>'اللغة المستهدفة','Target language'=>'اللغة الهدف','Target term'=>'المصطلح الهدف','Target: 140–160 chars for optimal SERP display'=>'الهدف: 140–160 حرفًا لعرض مثالي في نتائج البحث','Technical'=>'تقني','Technical / Scientific'=>'تقني / علمي','Technical / Scientific instructions'=>'تعليمات تقنية / علمية','Template "%s" already exists.'=>'القالب "%s" موجود بالفعل.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'القالب "{expected}" غير موجود — أنشئه في محرر الموقع أولاً.','Template has no content.'=>'القالب لا يحتوي على محتوى.','Template mode'=>'وضع النموذج','Template not found or not stored in the database.'=>'القالب غير موجود أو غير مخزن في قاعدة البيانات.','Template part "%s" already exists.'=>'جزء القالب "%s" موجود بالفعل.','Template part has no content.'=>'جزء القالب لا يحتوي على محتوى.','Template part not found or not stored in the database.'=>'جزء القالب غير موجود أو غير مخزن في قاعدة البيانات.','Template Parts'=>'أجزاء القالب','Templates'=>'القوالب','Test connection'=>'اختبار الاتصال','Testing…'=>'جارٍ الاختبار…','Text domain / locale'=>'نطاق النص / اللغة','Text to translate'=>'النص المراد ترجمته','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'ذاكرة تخزين استجابة API تخزن النتيجة الخام لكل طلب AI — الترجمة، الوصف التعريفي، المقتطف، وتوليد المحتوى — مع مفتاح بواسطة تجزئة المدخلات (المحتوى، زوج اللغة، المزود، النموذج). قم بإيقافها أثناء ضبط الطلب أو عندما تحتاج أن يصل كل طلب إلى مزود AI. تعطيلها لا يحذف الإدخالات المخزنة — إعادة تفعيلها يعيدها.','The editor did not accept the content — please try again.'=>'لم يقبل المحرر المحتوى — يرجى المحاولة مرة أخرى.','The following directive is active in your virtual robots.txt:'=>'التوجيه التالي نشط في ملف robots.txt الافتراضي الخاص بك:','The lf-social-share mu-plugin is active.'=>'الوحدة الإضافية lf-social-share نشطة.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'الوحدة الإضافية lf-social-share نشطة. مشاركة الوسائط الاجتماعية المدمجة من Lingua Forge غير نشطة — الوحدة الإضافية تتولى إعادة كتابة روابط المشاركة وإجراءات جافا سكريبت.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'يستخدم مستوى الضوء النموذج السريع المكون في جدول النماذج أعلاه (افتراضي: هايكو / فلاش). قم بالتبديل إلى الجودة إذا كنت بحاجة إلى نفس دقة الترجمة كوضع الصفحة الكاملة للمقتطفات.','The phrase as it appears in the source text.'=>'العبارة كما تظهر في النص المصدر.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'اللغة الأساسية دائمًا تُقدم في جذر موقعك — بدون بادئة URL في وضع المسار، بدون نطاق فرعي للغة في وضع النطاق الفرعي. تستخدم جميع اللغات الأخرى بادئة مسار /lang/ (مثل example.com/de/) أو نطاق فرعي للغة (مثل de.example.com)، اعتمادًا على إعداد بنية URL أدناه.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'تبويب SEO → التوافق يعرض حالة الكشف الحي ويشرح بدقة ما تفعله LF لكل منطقة من الميزات.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'رابط المشاركة يعكس دائمًا الصفحة الحالية — لا حاجة لإدخال عنوان URL يدويًا. يتيح لك مرشح linguaforge_social_share_url تجاوز عنوان URL المحلول لأي خدمة.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'يتم الإعلان عن خريطة الموقع تلقائيًا في robots.txt. تكتشف جميع محركات البحث الرئيسية — Google و Bing و Yandex — خريطة الموقع من robots.txt. لا حاجة لتقديمها يدويًا.','The source page has no footnotes.'=>'صفحة المصدر لا تحتوي على حواشي.','The upload failed — please try again.'=>'فشل التحميل — يرجى المحاولة مرة أخرى.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'تدرج خريطة الموقع الأساسية لـ WordPress جميع عناوين URL لمحتواك. تخبر خريطة موقع LF محركات البحث كيف ترتبط إصدارات اللغة ببعضها البعض عبر روابط xhtml:link hreflang. قدم كلاهما إلى Google Search Console للتغطية الكاملة.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'هذه الحواشي تأتي من صفحة المصدر وتعرض هنا للمرجعية فقط. أضفها إلى هذه الصفحة باستخدام محرر الكتل.','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'يتم تحديث هذا الكتالوج مع كل إصدار من Lingua Forge. اختبار الاتصال في علامة تبويب مفاتيح API يجلب أيضًا قائمة النماذج الحية من المزود ويحدث الاقتراحات أعلاه.','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'هذه صفحة نظام WooCommerce (متجر، عربة، الدفع، إلخ). يتم إدارة محتواها بواسطة WooCommerce — النتيجة تعكس إشارات هيكلية فقط، وليس محتوى SEO قابل للتحرير من قبل المستخدم.','This is the source page. Footnotes are edited directly in the block editor.'=>'هذه هي صفحة المصدر. يتم تحرير الحواشي مباشرة في محرر الكتل.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'هذا المفتاح يتم تزويده حاليًا من قبل خادم %s ولا يمكن إزالته هنا. أدخل مفتاحًا جديدًا أعلاه لتجاوز ذلك بقيمة من قاعدة البيانات.','This language is protected and cannot be uninstalled.'=>'هذه اللغة محمية ولا يمكن إلغاء تثبيتها.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'تطابق هذه اللغة إعدادات اللغة في WordPress ولا يمكن إلغاء تثبيتها.','Tier'=>'الطبقة','Tip: to reset a model to the built-in default, clear the field and save.'=>'نصيحة: لإعادة تعيين نموذج إلى الإعداد الافتراضي المدمج، امسح الحقل واحفظ.','Title'=>'العنوان','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'العنوان 15 نقطة · الوصف التعريفي 20 نقطة · عدد الكلمات 15 نقطة · العناوين 20 نقطة · الصور 10 نقاط · الروابط 10 نقاط. حد عنوان SERP 60 حرفًا؛ الوصف 120-210 حرف؛ التحذير من عدد الكلمات أدناه 300، الفشل أدناه 100؛ H2 مطلوب؛ الروابط الداخلية مطلوبة.','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'العنوان يحتوي على %1$d أحرف — قد يتم اختصاره في نتائج البحث (استهدف أقل من %2$d).','Title is only %d chars — aim for at least 10 characters.'=>'العنوان يحتوي على %d أحرف فقط — حاول أن تصل إلى 10 أحرف على الأقل.','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'قواعد تقييم العنوان (جميع الملفات الشخصية): الفشل إذا كان فارغًا؛ التحذير إذا كان أقل من 10 أحرف؛ التحذير إذا كان كلمة واحدة فقط؛ التحذير إذا كان أطول من حد SERP الخاص بالملف الشخصي (60 حرفًا للمدونة، 70 للمنتج/الصفحة المقصودة)؛ جيد إذا كان على الأقل 10 أحرف، على الأقل كلمتان، وضمن حد SERP.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'لاستخدام سر تشفير مخصص (بدلاً من قيمة wp_salt المستمدة)، أضف هذا إلى wp-config.php:','Today'=>'اليوم','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'استهلاك الرموز يتجمع حسب الميزة والمزود والطراز. يُسجل في كل مكالمة AI ناجحة؛ يتم استبعاد اختبار الاتصال لضمان عدم تحريف الإجماليات.','Tone'=>'نغمة','tone'=>'نغمة','Tone:'=>'نغمة:','Too many AI requests. Please retry in %d seconds.'=>'طلبات الذكاء الاصطناعي كثيرة جدًا. يرجى المحاولة مرة أخرى بعد %d ثوانٍ.','Total'=>'الإجمالي','Total tokens'=>'إجمالي الرموز','Translate'=>'ترجمة','Translate / Revise'=>'ترجمة / مراجعة','Translate / Revise block'=>'ترجمة / مراجعة الكتلة','Translate all'=>'ترجمة الكل','Translate chunk'=>'ترجمة الجزء','Translate Content'=>'ترجمة المحتوى','Translate missing'=>'الترجمة المفقودة','Translate page…'=>'ترجمة الصفحة…','Translated content'=>'المحتوى المترجم','Translated Names'=>'الأسماء المترجمة','Translated title'=>'العنوان المترجم','Translated to:'=>'مترجم إلى:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'تمت الترجمة. راجع في محرر الموقع — الروابط الداخلية، روابط التنقل، واسم القوالب لا يتم تحديثها تلقائيًا.','Translating…'=>'جارٍ الترجمة…','Translation'=>'الترجمة','Translation Caching'=>'ذاكرة التخزين المؤقت للترجمة','Translation found but permalink could not be generated'=>'تم العثور على الترجمة ولكن لم يتم إنشاء الرابط الدائم','Translation Limits'=>'حدود الترجمة','Translation Limits & Behavior'=>'حدود وسلوك الترجمة','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'حدود الترجمة: تحكم في الأدوار التي يمكنها تفعيل الترجمة بالذكاء الاصطناعي، وتحدد ميزانية رموز شهرية. تجاوز الميزانية يُوقف استدعاءات الذكاء الاصطناعي حتى بداية الشهر الجديد.','Translation Memory'=>'ذاكرة الترجمة','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'ذاكرة الترجمة تخزن نتائج الذكاء الاصطناعي بواسطة تجزئة المحتوى، زوج اللغة، المزود، والنموذج. تحرير منشور يلغي صلاحية الإدخال في الذاكرة بحيث تحصل على نتيجة جديدة في المرة التالية.','Translation Memory cleared. %d cached block was removed.'=>'تم مسح ذاكرة الترجمة المؤقتة. تم حذف كتلة مخزنة واحدة.' . "\0" . 'تم مسح ذاكرة الترجمة المؤقتة. تم حذف %d كتل مخزنة.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','Translation Memory setting saved.'=>'تم حفظ إعداد ذاكرة الترجمة.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'ذاكرة الترجمة: تخزن النص المترجم بالكامل لكل تجزئة محتوى. امسحها عندما تريد فرض إعادة ترجمة لجميع المنشورات بغض النظر عما إذا كانت محتوياتها قد تغيرت.','Translation workflow'=>'سير عمل الترجمة','Translation, Content Generator'=>'الترجمة، مولد المحتوى','Treat H2 as H1 equivalent'=>'معاملة H2 كـ H1 معادل','Type'=>'النوع','Uli Hake'=>'ولي هاك','Unexpected provider error (HTTP %d).'=>'خطأ غير متوقع من المزود (HTTP %d).','Uninstall %s'=>'إلغاء تثبيت %s','Uninstall Behaviour'=>'إلغاء تثبيت السلوك','Uninstall setting saved.'=>'تم حفظ إعداد إلغاء التثبيت.','unknown error'=>'خطأ غير معروف','Unknown provider.'=>'مزود غير معروف.','Unknown search engine.'=>'محرك بحث غير معروف.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'على عكس hreflang — حيث تتجاوز LF دائمًا المكونات الإضافية الأخرى لأنها لا يمكنها معرفة تكوينك متعدد اللغات — يختلف Open Graph: تقوم مكونات Yoast و Rank Math وغيرها بالفعل بإخراج علامات OG الصحيحة لمحتواك. تكرارها لا يضيف قيمة. في الوضع التلقائي، يكتشف LF المكونات الإضافية SEO النشطة ويضيف فقط ما لا يمكنها توفيره: og:locale (اللغة الحالية) و og:locale:alternate (جميع اللغات الأخرى المُعدة).','Unlimited'=>'غير محدود','Up'=>'أعلى','Upload .mo file'=>'تحميل ملف .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'قم بتحميل ملفات .mo المجمعة لتجاوز سلاسل الإضافات الخارجية للغات المحددة — على سبيل المثال، ترجمة VikBooking مخصصة تستخدم "شقة" بدلاً من "غرفة". يجب أن تتبع الملفات نمط تسمية ووردبريس: {textdomain}-{locale}.mo (مثال: vikbooking-ca.mo). يتم تخزينها في مجلد التحميلات وتظل بعد تحديث الإضافة.','Upload Override'=>'تحميل التجاوز','URL could not be mapped to a post — check the link target exists'=>'تعذر ربط عنوان URL بمنشور — تحقق من وجود الهدف الرابط','URL structure'=>'بنية URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'هيكل URL: وضع بادئة المسار (example.com/de/) لا يتطلب تغييرات في الخادم. وضع النطاق الفرعي (de.example.com) يتطلب سجل DNS عام، وشهادة SSL عامة، وتغيير في إعدادات خادم الويب — راجع دليل إعداد الخادم.','URL to enter'=>'عنوان URL للدخول إليه','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'استخدم المشاركة الأصلية عند توفرها؛ وارجع إلى النسخ المنسوخة من الحافظة. التوصية الافتراضية لأزرار "مشاركة".','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'استخدم علامات التبويب في أعلى هذه الصفحة لضبط كل منطقة. التغييرات على علامة التبويب الموجه تأخذ مفعولها فورًا؛ التغييرات على مفاتيح الذكاء الاصطناعي وإعدادات النموذج تنطبق على الطلب التالي.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'جدول المصطلحات الذي يديره المستخدم لكل زوج لغة. يتم إرفاق الإدخالات بموجه نظام الترجمة بحيث يستخدم الذكاء الاصطناعي المصطلحات المفضلة بشكل متسق — وهو أمر حاسم لمفردات المجال ("kWp"، "PPA"، "نقطة الاتصال")، أسماء العلامات التجارية التي لا يجب ترجمتها، والعبارات التنظيمية الموحدة. كلا حقلَي اللغة اختياريان: اترك "اللغة المصدر" فارغة لتطبيق الإدخال بغض النظر عن اللغة التي تترجم منها؛ اترك "اللغة الهدف" فارغة لتطبيقه على جميع اللغات الهدف مرة واحدة.','Using custom meta description.'=>'استخدام وصف ميتا مخصص.','Using LF AI meta description.'=>'استخدام وصف ميتا AI من LF.','Value source'=>'مصدر القيمة','Version'=>'الإصدار','View'=>'عرض','View built-in default'=>'عرض الإعداد الافتراضي المدمج','View current robots.txt'=>'عرض ملف robots.txt الحالي','View details'=>'عرض التفاصيل','View Lingua Forge details'=>'عرض تفاصيل لينغا فورج','Visit plugin site'=>'زيارة موقع الإضافة','Warning:'=>'تحذير:','WcPageBridge active'=>'وحدة WcPageBridge نشطة','WebSite'=>'موقع ويب','WebSite — front page / blog index'=>'موقع ويب — الصفحة الرئيسية / فهرس المدونة','What LF provides — and collision avoidance'=>'ما يقدمه LF — وتجنب التصادم','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'ما يقدمه LF: علامات hreflang لكل لغة مُعدة، علامات Open Graph وتويتر كارد مع og:locale و og:locale:alternate، JSON-LD من Schema.org مع تعليقات inLanguage، وخريطة موقع متعددة اللغات مخصصة على /lf-sitemap.xml مع إدخالات xhtml:link بديلة لجميع مجموعات الترجمة.','When another SEO plugin is installed'=>'عند تثبيت مكون إضافي SEO آخر','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'عندما يتم تفعيل تسجيل التصحيح (عبر التبديل أدناه أو بتعريف LINGUAFORGE_AI_DEBUG في wp-config.php)، تكتب ميزات ترجمة القالب وترجمة الترجمة FSE مطالبات الذكاء الاصطناعي واستجاباتهما إلى القرص لأغراض استكشاف الأخطاء وإصلاحها. استخدم هذا القسم لمراقبة تلك المخرجات ومسحها بمجرد أن تحصل على ما تحتاجه — يمكن أن تنمو الملفات بسرعة على الصفحات الكبيرة. قم بتكوين دليل الوجهة عبر مرشح linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'عند التمكين، يتم إعادة توجيه الزائرين لأول مرة الذين لا يملكون كوكي لغة ولا يوجد بادئة لغة في عنوان URL إلى أقرب إصدار مطابق للغة. يتم تخطي إعادة التوجيه إذا لم تكن اللغة المفضلة للمتصفح من بين لغات الموجه النشطة. بمجرد أن يختار الزائر لغة عبر المبدل، تأخذ الكوكي الأولوية ويتم تجاهل رأس المتصفح في جميع الزيارات المستقبلية.','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'عند التفعيل، يُصدر Lingua Forge العلامات الوصفية الإضافية التالية على صفحات المنتجات: og:type=product، og:price:amount، og:price:currency، og:availability، وما يعادلها من مساحة أسماء المنتج المستخدمة بواسطة Facebook Catalog.','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'عند التفعيل، يتم الإعلان عن عنوان URL لخريطة الموقع في robots.txt تلقائيًا ويتم تحديث التخزين المؤقت عند حفظ المحتوى المترجم.','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'عندما يتطلب ملف تعريف المدونة وجود H2 ولم يتم العثور عليه، يتحقق المحلل أولاً من وجود عناوين فرعية H3 قبل إصدار تحذير. أقسام الأكورديون والتفاصيل افتراضيًا تستخدم H3 لعناوينها؛ تُقبل تلك H3 كهيكل صالح وتنتج نتيجة جيدة، وليس تحذيرًا.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'عند تفعيل Yoast SEO، Rank Math، All in One SEO، أو SEOPress، يقوم Lingua Forge تلقائيًا بكتم إخراج hreflang الخاص بهم عبر مرشح. مكونات SEO العامة تنتج hreflang استنادًا إلى بنية عنوان URL بلغة واحدة ولا يمكنها مراعاة تكوين التوجيه متعدد اللغات الخاص بك؛ إخراج LF دائمًا صحيح.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'أي طبقة نموذج لاستخدامها للترجمة الكاملة للصفحة. الجودة تستخدم النموذج المكون في جدول النماذج أعلاه ويوصى بها للترجمة الدقيقة والطويلة. انتقل إلى الخفيف فقط إذا كانت السرعة أو التكلفة أولوية والمحتوى قصير.','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'أثناء التفعيل، تتولى الوحدة الإضافية الأساسية OG مجموعة وتصدر LF علامات اللغة فقط (وضع تلقائي). إزالتها تُحول LF تلقائيًا إلى وضع OG كامل.','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'WooCommerce غير نشط.','WooCommerce page translations'=>'ترجمات صفحات WooCommerce','WooCommerce product price'=>'سعر منتج WooCommerce','WooCommerce SEO settings saved.'=>'تم حفظ إعدادات SEO لـ WooCommerce.','WooCommerce store currency'=>'عملة متجر WooCommerce','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'صفحات نظام WooCommerce (متجر، عربة، دفع، حسابي) مستثناة — محتواها يُدار بواسطة WooCommerce ولا يمكن تحسينه من خلال تعديلات SEO.','WooCommerce version'=>'إصدار WooCommerce','Word count'=>'عدد الكلمات','WordPress version'=>'إصدار ووردبريس','WP core canonical active (hreflang disabled)'=>'تم تفعيل canonical الخاص بـ WP (تعطيل hreflang)','WP instance language'=>'لغة مثيل ووردبريس','WP-CLI reference'=>'مرجع WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'كتابة مطالبات واستجابات الذكاء الاصطناعي إلى القرص لأغراض استكشاف الأخطاء وإصلاحها','XML Sitemap'=>'خريطة الموقع XML','Yes'=>'نعم','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'يمكنك أيضًا تعريف المفاتيح كثوابت أو متغيرات بيئة (على سبيل المثال في wp-config.php). تُستخدم هذه المصادر تلقائيًا كبديل عند عدم وجود مفتاح مخزن في قاعدة البيانات.','You do not have permission to manage these settings.'=>'ليس لديك إذن لإدارة هذه الإعدادات.','You do not have permission to read this post.'=>'ليس لديك إذن لقراءة هذا المنشور.','{n} stale path(s)'=>'{n} مسار قديم','~%d min read'=>'~%d دقيقة للقراءة' . "\0" . '~%d دقيقة للقراءة' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','— AI features are disabled.'=>'— ميزات الذكاء الاصطناعي معطّلة.','— Any source language —'=>'— أي لغة مصدر —','— Any target language —'=>'— أي لغة هدف —','— Any target —'=>'— أي هدف —','— Any —'=>'— أي —','— Auto-detect —'=>'— اكتشاف تلقائي —','— auto-detect —'=>'— اكتشاف تلقائي —','— Deferred to plugin'=>'— تم تأجيله إلى المكون الإضافي','— Disabled'=>'— معطل','— Not detected'=>'— لم يتم الكشف عنه','— select a language —'=>'— اختر لغة —','← Back'=>'← العودة','↑ Detected from current post'=>'↑ تم اكتشافه من المنشور الحالي','→ Locale tags only (manual setting)'=>'→ علامات اللغة فقط (إعداد يدوي)','→ Locale tags only — deferring base OG to plugin'=>'→ علامات اللغة فقط — تأجيل قاعدة OG إلى الإضافة','↺ Re-translate'=>'↺ إعادة الترجمة','↺ Refine'=>'↺ تحسين','↺ Refresh'=>'↺ تحديث','↺ Refresh AI Analysis'=>'↺ تحديث تحليل الذكاء الاصطناعي','↺ Refreshing…'=>'↺ جارٍ التحديث…','⚠ Borderline'=>'⚠ على الحد الفاصل','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ لم يتم العثور على منشورات <strong>{lang}</strong>. تأكد من أن جميع المنشورات المترجمة تحتوي على متغير اللغة مضبوط على <strong>{lang}</strong> في مربع بيانات اللغة.','⚠ No changes'=>'⚠ لا تغييرات','⚠ No changes — re-scan?'=>'⚠ لا تغييرات — إعادة الفحص؟','✅ Fixed ({n})'=>'✅ تم الإصلاح ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ لم يتم العثور على روابط مكسورة أو تطابقات قالب خاطئة لـ <strong>{lang}</strong>. تم فحص <strong>{scanned}</strong> منشورًا و صفحة — جميع الفحوصات ناجحة. روابط أجزاء القالب (رأس الصفحة، تذييل الصفحة، الشريط الجانبي) غير مشمولة هنا — استخدم زر إصلاح أجزاء القالب لفحصها بشكل منفصل.','✅ Template fixed'=>'✅ تم إصلاح القالب','✓ %s notified successfully.'=>'✓ %s تم الإبلاغ عنه بنجاح.','✓ Active'=>'✓ نشط','✓ Active at /lf-sitemap.xml'=>'✓ نشط على /lf-sitemap.xml','✓ Active — %d URL entry with language alternates'=>'✓ نشط — إدخال عنوان URL / %d مع بدائل اللغة' . "\0" . '✓ نشط — إدخالات عنوان URL / %d مع بدائل اللغة' . "\0